                                <ResponsiveContainer width="100%" height={300}>
                                    <BarChart data={campaigns}>
                                        <CartesianGrid strokeDasharray="3 3" stroke="#4A5568" />
                                        <XAxis dataKey="name" stroke="#A0AEC0" />
                                        <YAxis yAxisId="left" orientation="left" stroke="#A0AEC0" label={{ value: 'Amount Spent ($)', angle: -90, position: 'insideLeft', fill: '#A0AEC0' }} />
                                        <YAxis yAxisId="right" orientation="right" stroke="#63B3ED" label={{ value: 'ROAS', angle: 90, position: 'insideRight', fill: '#63B3ED' }} />
                                        <Tooltip contentStyle={{ backgroundColor: '#1A202C', border: '1px solid #4A5568' }} />
                                        <Legend />
                                        <Bar yAxisId="left" dataKey="spend" fill="#2B6CB0" name="Spend" />
                                        <Bar yAxisId="right" dataKey="roas" fill="#63B3ED" name="ROAS" />
                                    </BarChart>
                                </ResponsiveContainer>
                            </div>
                           <div className="bg-gray-800 p-6 rounded-lg shadow-xl">
                                <h3 className="text-xl font-semibold mb-4 text-white">Impressions vs Clicks by Campaign</h3>
                                 <ResponsiveContainer width="100%" height={300}>
                                    <LineChart data={campaigns}>
                                        <CartesianGrid strokeDasharray="3 3" stroke="#4A5568" />
                                        <XAxis dataKey="name" stroke="#A0AEC0" />
                                        <YAxis stroke="#A0AEC0" />
                                        <Tooltip contentStyle={{ backgroundColor: '#1A202C', border: '1px solid #4A5568' }} />
                                        <Legend />
