import { GoogleGenAI, GenerateContentResponse } from "@google/genai";
import { Campaign, AnalysisSummary } from '../types';

export const getRecommendations = async (campaigns: Campaign[], summary: AnalysisSummary): Promise<string> => {
    if (!process.env.API_KEY) {
        throw new Error("API_KEY environment variable not set");
    }

    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    const prompt = `
        You are a world-class Meta Ads campaign analysis expert. Your task is to analyze the following campaign performance data and provide actionable recommendations.
        The data is provided in JSON format.

        **Overall Summary:**
        ${JSON.stringify(summary, null, 2)}

        **Individual Campaign Data:**
        ${JSON.stringify(campaigns, null, 2)}

        Please provide your analysis in clear, concise Markdown format with the following structure:

        **Overall Performance Summary:**
        A brief overview of the key metrics like Total Spend, Total Purchases, and overall ROAS. Comment on the general health of the ad account based on this data.

        **Top Performing Campaigns:**
        Identify 1-2 campaigns with the best ROAS or lowest Cost Per Purchase. Explain why they might be succeeding (e.g., high ROAS despite moderate spend).

        **Underperforming Campaigns:**
        Identify 1-2 campaigns with low ROAS or other poor metrics. Suggest potential reasons for their poor performance (e.g., high spend with low returns, low CTR).

        **Actionable Recommendations:**
        Provide a numbered list of 3-5 specific, concrete steps the user can take to improve their campaigns. These should be tactical and easy to understand. For example:
        * "Consider reallocating budget from 'Campaign E' to 'Campaign C' to maximize return, given Campaign C's 5.2x ROAS."
        * "Investigate the ad creative and audience targeting for 'Campaign B'. Its primary goal seems to be awareness, but a CTR of 0.6% is very low. A/B test new visuals or ad copy to improve engagement."
        * "Analyze the conversion funnel for 'Campaign D'. Despite high spend, the ROAS is average. Is there a drop-off on the landing page or during checkout?"

        **Opportunities:**
        Highlight any potential opportunities for growth or testing based on the data. For instance, scaling a successful campaign or testing a new audience segment.

        Your response should be easy for a marketer to understand and act upon.
    `;

    try {
        const response: GenerateContentResponse = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: prompt,
        });
        return response.text;
    } catch (error) {
        console.error("Error calling Gemini API:", error);
        throw new Error("Failed to get recommendations from AI. Please check the API key and try again.");
    }
};

export interface Campaign {
    name: string;
    spend: number;
    impressions: number;
    clicks: number;
    purchases: number;
    roas: number;
    ctr: number;
    cpc: number;
    cpm: number;
    cpp: number;
}

export interface AnalysisSummary {
    totalSpend: number;
    totalImpressions: number;
    totalClicks: number;
    totalPurchases: number;
    overallROAS: number;
    avgCTR: number;
    avgCPC: number;
    avgCPM: number;
    avgCPP: number;
}

import { Campaign, AnalysisSummary } from '../types';

// A more robust header mapping to handle variations in CSV column names.
const HEADER_MAPPINGS: { [key: string]: keyof Omit<Campaign, 'ctr' | 'cpc' | 'cpm' | 'cpp'> } = {
    'campaign name': 'name',
    'amount spent (usd)': 'spend',
    'spend': 'spend',
    'impressions': 'impressions',
    'clicks': 'clicks',
    'purchases': 'purchases',
    'conversions': 'purchases',
    'purchase roas (return on ad spend)': 'roas',
    'roas': 'roas'
};

const getHeaderIndex = (headers: string[], possibleNames: string[]): number => {
    for (const name of possibleNames) {
        const index = headers.indexOf(name);
        if (index !== -1) return index;
    }
    return -1;
};

export const parseAndProcessData = (csvData: string): { campaigns: Campaign[], summary: AnalysisSummary } => {
    const lines = csvData.trim().split('\n');
    if (lines.length < 2) {
        throw new Error('CSV data must have at least one header row and one data row.');
    }

    const rawHeaders = lines[0].split(',').map(h => h.trim().toLowerCase());
    const dataRows = lines.slice(1);

    const headerMap: { [key in keyof Omit<Campaign, 'ctr' | 'cpc' | 'cpm' | 'cpp'>]: number } = {
        name: getHeaderIndex(rawHeaders, ['campaign name']),
        spend: getHeaderIndex(rawHeaders, ['amount spent (usd)', 'spend']),
        impressions: getHeaderIndex(rawHeaders, ['impressions']),
        clicks: getHeaderIndex(rawHeaders, ['clicks']),
        purchases: getHeaderIndex(rawHeaders, ['purchases', 'conversions']),
        roas: getHeaderIndex(rawHeaders, ['purchase roas (return on ad spend)', 'roas']),
    };

    // Validate that all required headers are found
    for (const key in headerMap) {
        if (headerMap[key as keyof typeof headerMap] === -1) {
            throw new Error(`Missing required CSV column: ${key}. Please check your data.`);
        }
    }

    const campaigns: Campaign[] = dataRows.map(row => {
        const values = row.split(',');

        const name = values[headerMap.name].trim();
        const spend = parseFloat(values[headerMap.spend]) || 0;
        const impressions = parseInt(values[headerMap.impressions], 10) || 0;
        const clicks = parseInt(values[headerMap.clicks], 10) || 0;
        const purchases = parseInt(values[headerMap.purchases], 10) || 0;
        const roas = parseFloat(values[headerMap.roas]) || 0;

        // Calculated metrics
        const ctr = impressions > 0 ? (clicks / impressions) * 100 : 0;
        const cpc = clicks > 0 ? spend / clicks : 0;
        const cpm = impressions > 0 ? (spend / impressions) * 1000 : 0;
        const cpp = purchases > 0 ? spend / purchases : 0;

        return { name, spend, impressions, clicks, purchases, roas, ctr, cpc, cpm, cpp };
    }).filter(c => c.name); // Filter out empty rows

    if (campaigns.length === 0) {
        throw new Error('No valid campaign data could be parsed from the CSV.');
    }

    const summary: AnalysisSummary = campaigns.reduce((acc, campaign) => {
        acc.totalSpend += campaign.spend;
        acc.totalImpressions += campaign.impressions;
        acc.totalClicks += campaign.clicks;
        acc.totalPurchases += campaign.purchases;
        return acc;
    }, {
        totalSpend: 0,
        totalImpressions: 0,
        totalClicks: 0,
        totalPurchases: 0,
        overallROAS: 0,
        avgCTR: 0,
        avgCPC: 0,
        avgCPM: 0,
        avgCPP: 0
    });

    summary.overallROAS = summary.totalSpend > 0 ? (summary.totalSpend * (campaigns.reduce((sum, c) => sum + c.roas * c.spend, 0) / campaigns.reduce((sum, c) => sum + c.spend, 1))) / summary.totalSpend : 0;
    summary.avgCTR = summary.totalImpressions > 0 ? (summary.totalClicks / summary.totalImpressions) * 100 : 0;
    summary.avgCPC = summary.totalClicks > 0 ? summary.totalSpend / summary.totalClicks : 0;
    summary.avgCPM = summary.totalImpressions > 0 ? (summary.totalSpend / summary.totalImpressions) * 1000 : 0;
    summary.avgCPP = summary.totalPurchases > 0 ? summary.totalSpend / summary.totalPurchases : 0;

    return { campaigns, summary };
};

import React, { useState, useCallback, useMemo } from 'react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer, LineChart, Line } from 'recharts';
import { KpiCard } from './components/KpiCard';
import { Campaign, AnalysisSummary } from './types';
import { parseAndProcessData } from './utils/dataProcessor';
import { getRecommendations } from './services/geminiService';
import { DollarSignIcon, TargetIcon, EyeIcon, PointerIcon, UsersIcon } from './components/icons';

const App: React.FC = () => {
    const [csvData, setCsvData] = useState<string>('');
    const [campaigns, setCampaigns] = useState<Campaign[]>([]);
    const [summary, setSummary] = useState<AnalysisSummary | null>(null);
    const [recommendations, setRecommendations] = useState<string>('');
    const [isLoading, setIsLoading] = useState<boolean>(false);
    const [error, setError] = useState<string>('');

    const handleAnalyze = useCallback(async () => {
        if (!csvData.trim()) {
            setError('Please paste your CSV data first.');
            return;
        }
        setIsLoading(true);
        setError('');
        setRecommendations('');
        setCampaigns([]);
        setSummary(null);

        try {
            const { campaigns: parsedCampaigns, summary: analysisSummary } = parseAndProcessData(csvData);
            setCampaigns(parsedCampaigns);
            setSummary(analysisSummary);

            const aiRecommendations = await getRecommendations(parsedCampaigns, analysisSummary);
            setRecommendations(aiRecommendations);

        } catch (e: any) {
            setError(`Analysis failed: ${e.message}`);
            console.error(e);
        } finally {
            setIsLoading(false);
        }
    }, [csvData]);

    const exampleCSV = `Campaign Name,Amount Spent (USD),Impressions,Clicks,Purchases,Purchase ROAS (return on ad spend),Audience
Campaign A - Summer Sale,1500,120000,2400,50,4.5,"Fitness Enthusiasts (25-40)"
Campaign B - Brand Awareness,800,250000,1500,10,2.1,"Tech Early Adopters"
Campaign C - Retargeting,2200,85000,3200,85,5.2,"Past Website Visitors"
Campaign D - New Product Launch,3000,150000,2000,60,3.0,"Tech Early Adopters"
Campaign E - Low Performer,500,30000,250,5,1.5,"Fitness Enthusiasts (25-40)"
Campaign F - High ROAS Test,1200,95000,2800,75,6.1,"Past Website Visitors"`;

    const handleUseExample = () => {
        setCsvData(exampleCSV);
        setError('');
    };

    const audiencePerformance = useMemo(() => {
        if (campaigns.length === 0) return [];

        const audienceMap = new Map<string, { totalSpend: number; totalRevenue: number }>();

        campaigns.forEach(campaign => {
            if (campaign.audience && campaign.audience !== 'N/A') {
                const stats = audienceMap.get(campaign.audience) || { totalSpend: 0, totalRevenue: 0 };
                stats.totalSpend += campaign.spend;
                stats.totalRevenue += campaign.spend * campaign.roas;
                audienceMap.set(campaign.audience, stats);
            }
        });

        const performanceData = Array.from(audienceMap.entries()).map(([audience, stats]) => ({
            audience,
            spend: stats.totalSpend,
            roas: stats.totalSpend > 0 ? stats.totalRevenue / stats.totalSpend : 0,
        }));

        return performanceData.sort((a, b) => b.roas - a.roas);
    }, [campaigns]);

    const bestAudience = useMemo(() => {
        if (audiencePerformance.length === 0) return { name: 'N/A', value: 'N/A' };
        const topAudience = audiencePerformance[0];
        return { name: topAudience.audience, value: `${topAudience.roas.toFixed(2)}x ROAS` };
    }, [audiencePerformance]);


    const formattedRecommendations = useMemo(() => {
        if (!recommendations) return null;
        return recommendations
            .split('\n')
            .map((line, index) => {
                if (line.startsWith('**')) {
                    return <h3 key={index} className="text-xl font-bold mt-4 mb-2 text-blue-400">{line.replace(/\*\*/g, '')}</h3>;
                }
                if (line.startsWith('* ')) {
                    return <li key={index} className="ml-6 list-disc">{line.substring(2)}</li>;
                }
                if (/^\d+\./.test(line)) {
                    return <li key={index} className="ml-6 my-1">{line}</li>;
                }
                return <p key={index} className="my-1">{line}</p>;
            });
    }, [recommendations]);

    return (
        <div className="min-h-screen bg-gray-900 text-gray-100 font-sans">
            <header className="bg-gray-800/50 backdrop-blur-sm shadow-lg p-4 sticky top-0 z-10">
                <div className="container mx-auto flex justify-between items-center">
                    <h1 className="text-2xl font-bold text-white">Meta Ads Performance Analyzer</h1>
                </div>
            </header>

            <main className="container mx-auto p-4 md:p-8">
                <div className="bg-gray-800 rounded-lg shadow-2xl p-6 mb-8">
                    <h2 className="text-2xl font-semibold mb-4 text-blue-300">Input Your Campaign Data</h2>
                    <p className="text-gray-400 mb-4">Paste your campaign data in CSV format below. Include an 'Audience' column for deeper insights.</p>
                    <textarea
                        className="w-full h-48 p-3 bg-gray-900 border border-gray-700 rounded-md focus:ring-2 focus:ring-blue-500 focus:outline-none transition-shadow text-gray-200"
                        placeholder={exampleCSV}
                        value={csvData}
                        onChange={(e) => setCsvData(e.target.value)}
                    />
                    <div className="flex flex-col sm:flex-row items-center justify-between mt-4 space-y-4 sm:space-y-0 sm:space-x-4">
                        <button
                            onClick={handleUseExample}
                            className="w-full sm:w-auto px-6 py-2 bg-gray-700 hover:bg-gray-600 rounded-md font-semibold transition-colors"
                        >
                            Use Example Data
                        </button>
                        <button
                            onClick={handleAnalyze}
                            disabled={isLoading}
