import { GoogleGenAI, GenerateContentResponse } from "@google/genai";
import { Campaign, AnalysisSummary } from '../types';

export const getRecommendations = async (campaigns: Campaign[], summary: AnalysisSummary): Promise<string> => {
    if (!process.env.API_KEY) {
        throw new Error("API_KEY environment variable not set");
    }

    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    const hasAudienceData = campaigns.some(c => c.audience && c.audience !== 'N/A');

    const prompt = `
        You are 'THE WOLF OF ADS', the world's greatest media buyer, known for turning ad spend into massive profits. Your advice is direct, brutally honest, and hyper-focused on scaling what works and killing what doesn't. You don't waste time on vanity metrics. You care about one thing: Return On Ad Spend (ROAS).

        Analyze the following Meta Ads campaign data like a top-tier performance marketer.

        **Overall Summary:**
        ${JSON.stringify(summary, null, 2)}

        **Raw Campaign Data:**
        ${JSON.stringify(campaigns, null, 2)}

        Provide your analysis in aggressive, actionable Markdown format. Use this structure:

        **THE BOTTOM LINE:**
        Start with a no-BS summary of the account's health. Is it making money or burning cash? What's the overall ROAS? Be direct.

        **KILL OR SCALE: Campaign Breakdown**
        *   **SCALE IT 🚀:** Identify the top 1-2 campaigns that are printing money (highest ROAS). Explain exactly WHY they are winning and give an aggressive scaling plan (e.g., "Crank up the budget by 30% now.").
        *   **KILL IT 🔪:** Identify the 1-2 worst-performing campaigns that are bleeding money. Be ruthless. Tell the user to pause them immediately and explain why they're failing (e.g., "This campaign has a 1.5x ROAS. You're losing money. Shut it down yesterday.").

        ${hasAudienceData ? `
        **GOLDMINE AUDIENCES:**
        This is where the real money is made.
        *   **Winning Audiences:** Pinpoint the exact audiences with the highest ROAS. Tell the user to double down on these.
        *   **Loser Audiences:** Pinpoint the audiences that are a waste of money. Tell the user to stop targeting them.
        *   **Alpha Insight:** Provide a key insight about their audiences. Are retargeting audiences carrying all the weight? Is a specific prospecting audience showing potential?
        ` : ''}

        **IMMEDIATE ACTION PLAN (Your Roadmap to Profit):**
        Give a numbered list of 3-5 high-impact, immediate actions. This is a direct order list.
        1.  **Budget Reallocation:** Be specific. "ACTION: Pause Campaign E immediately. Reallocate its entire daily budget to Campaign C and Campaign F, splitting it 50/50."
        2.  **Audience & Targeting:** Be precise. "ACTION: The 'Past Website Visitors' audience is your goldmine. Create a new ad set targeting a 1% Lookalike Audience in your primary market based on these converters. Exclude recent purchasers."
        3.  **Creative Testing:** Give a clear testing instruction. "ACTION: The creative in your winning campaigns is working. Duplicate the ads from Campaign F into a new ad set targeting your best Lookalike audience. Don't change a thing."
        4.  **Kill a Loser:** Reiterate the need to cut losses. "ACTION: I already told you to kill Campaign E. If you haven't done it yet, do it now. Stop wasting money."

        Your tone must be confident, expert, and laser-focused on maximizing profit. No fluff. Just actionable, money-making advice.
    `;

    try {
        const response: GenerateContentResponse = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: prompt,
        });
        return response.text;
    } catch (error) {
        console.error("Error calling Gemini API:", error);
        throw new Error("Failed to get recommendations from AI. Please check the API key and try again.");
    }
};

import React, { useState, useCallback, useMemo } from 'react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer, LineChart, Line } from 'recharts';
import { KpiCard } from './components/KpiCard';
import { Campaign, AnalysisSummary } from './types';
import { parseAndProcessData } from './utils/dataProcessor';
import { getRecommendations } from './services/geminiService';
import { DollarSignIcon, TargetIcon, EyeIcon, PointerIcon, UsersIcon, UploadIcon, SendIcon } from './components/icons';
import { generateEmailHtml } from './utils/emailGenerator';

const App: React.FC = () => {
    const [csvData, setCsvData] = useState<string>('');
    const [fileName, setFileName] = useState<string>('');
    const [campaigns, setCampaigns] = useState<Campaign[]>([]);
    const [summary, setSummary] = useState<AnalysisSummary | null>(null);
    const [recommendations, setRecommendations] = useState<string>('');
    const [isLoading, setIsLoading] = useState<boolean>(false);
    const [error, setError] = useState<string>('');

    const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
        const file = event.target.files?.[0];
        if (file) {
            setFileName(file.name);
            const reader = new FileReader();
            reader.onload = (e) => {
                const text = e.target?.result;
                if (typeof text === 'string') {
                    setCsvData(text);
                    setError('');
                } else {
                    setError('Failed to read file content.');
                }
            };
            reader.onerror = () => {
                setError('Error reading the file.');
            };
            reader.readAsText(file);
        }
    };

    const handleAnalyze = useCallback(async () => {
        if (!csvData.trim()) {
            setError('Please upload a CSV file or use the example data first.');
            return;
        }
        setIsLoading(true);
        setError('');
        setRecommendations('');
        setCampaigns([]);
        setSummary(null);

        try {
            const { campaigns: parsedCampaigns, summary: analysisSummary } = parseAndProcessData(csvData);
            setCampaigns(parsedCampaigns);
            setSummary(analysisSummary);

            const aiRecommendations = await getRecommendations(parsedCampaigns, analysisSummary);
            setRecommendations(aiRecommendations);

        } catch (e: any) {
            setError(`Analysis failed: ${e.message}`);
            console.error(e);
        } finally {
            setIsLoading(false);
        }
    }, [csvData]);

    const exampleCSV = `Campaign Name,Amount Spent (USD),Impressions,Clicks,Purchases,Purchase ROAS (return on ad spend),Audience
Campaign A - Summer Sale,1500,120000,2400,50,4.5,"Fitness Enthusiasts (25-40)"
Campaign B - Brand Awareness,800,250000,1500,10,2.1,"Tech Early Adopters"
Campaign C - Retargeting,2200,85000,3200,85,5.2,"Past Website Visitors"
Campaign D - New Product Launch,3000,150000,2000,60,3.0,"Tech Early Adopters"
Campaign E - Low Performer,500,30000,250,5,1.5,"Fitness Enthusiasts (25-40)"
Campaign F - High ROAS Test,1200,95000,2800,75,6.1,"Past Website Visitors"`;

    const handleUseExample = () => {
        setCsvData(exampleCSV);
        setFileName('facebook_ads_export_example.csv');
        setError('');
    };

    const audiencePerformance = useMemo(() => {
        if (campaigns.length === 0) return [];

        const audienceMap = new Map<string, { totalSpend: number; totalRevenue: number }>();

        campaigns.forEach(campaign => {
            if (campaign.audience && campaign.audience !== 'N/A') {
                const stats = audienceMap.get(campaign.audience) || { totalSpend: 0, totalRevenue: 0 };
                stats.totalSpend += campaign.spend;
                stats.totalRevenue += campaign.spend * campaign.roas;
                audienceMap.set(campaign.audience, stats);
            }
        });

        const performanceData = Array.from(audienceMap.entries()).map(([audience, stats]) => ({
            audience,
            spend: stats.totalSpend,
            roas: stats.totalSpend > 0 ? stats.totalRevenue / stats.totalSpend : 0,
        }));

        return performanceData.sort((a, b) => b.roas - a.roas);
    }, [campaigns]);

    const bestAudience = useMemo(() => {
        if (audiencePerformance.length === 0) return { name: 'N/A', value: 'N/A' };
        const topAudience = audiencePerformance[0];
        return { name: topAudience.audience, value: `${topAudience.roas.toFixed(2)}x ROAS` };
    }, [audiencePerformance]);


    const formattedRecommendations = useMemo(() => {
        if (!recommendations) return null;
        return recommendations
            .split('\n')
            .map((line, index) => {
                if (line.startsWith('**')) {
                    return <h3 key={index} className="text-xl font-bold mt-4 mb-2 text-blue-400">{line.replace(/\*\*/g, '')}</h3>;
                }
                 if (line.startsWith('*   **')) { // For bolded list items
                    return <li key={index} className="ml-6 list-disc" dangerouslySetInnerHTML={{ __html: line.substring(2).replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>') }}></li>;
                }
                if (line.startsWith('* ')) {
                    return <li key={index} className="ml-6 list-disc">{line.substring(2)}</li>;
                }
                if (/^\d+\./.test(line)) {
                    return <li key={index} className="ml-6 my-1" dangerouslySetInnerHTML={{ __html: line.replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>') }}></li>;
                }
                return <p key={index} className="my-1">{line}</p>;
            });
    }, [recommendations]);

    const handleSendEmail = () => {
        if (!recommendations || !summary) return;

        const emailBody = generateEmailHtml(recommendations, summary);
        const subject = "Meta Ads Performance Analysis Report";
        const mailtoLink = `mailto:Karim.wmbox@gmail.com?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(emailBody)}`;

        window.location.href = mailtoLink;
    };


    return (
        <div className="min-h-screen bg-gray-900 text-gray-100 font-sans">
            <header className="bg-gray-800/50 backdrop-blur-sm shadow-lg p-4 sticky top-0 z-10">
                <div className="container mx-auto flex justify-between items-center">
                    <h1 className="text-2xl font-bold text-white">Meta Ads Performance Analyzer</h1>
                </div>
            </header>

            <main className="container mx-auto p-4 md:p-8">
                <div className="bg-gray-800 rounded-lg shadow-2xl p-6 mb-8">
                    <h2 className="text-2xl font-semibold mb-4 text-blue-300">Upload Your Campaign Export</h2>
                    <div className="flex flex-col items-center justify-center w-full mt-4">
                        <label htmlFor="csv-upload" className="flex flex-col items-center justify-center w-full h-48 border-2 border-gray-600 border-dashed rounded-lg cursor-pointer bg-gray-900 hover:bg-gray-700 transition-colors">
                            <div className="flex flex-col items-center justify-center pt-5 pb-6 text-center">
                                <UploadIcon />
                                 {fileName ? (
                                    <p className="font-semibold text-green-400">{fileName}</p>
                                ) : (
                                    <>
                                        <p className="mb-2 text-sm text-gray-400">
                                            <span className="font-semibold">Click to upload</span> or drag and drop
                                        </p>
                                        <p className="text-xs text-gray-500">CSV file from Facebook Business Manager</p>
                                    </>
                                )}
                            </div>
                            <input id="csv-upload" type="file" className="hidden" accept=".csv, text/csv" onChange={handleFileChange} />
                        </label>
                    </div>

                    <div className="flex flex-col sm:flex-row items-center justify-between mt-6 space-y-4 sm:space-y-0 sm:space-x-4">
                        <button
                            onClick={handleUseExample}
                            className="w-full sm:w-auto px-6 py-2 bg-gray-700 hover:bg-gray-600 rounded-md font-semibold transition-colors"
                        >
                            Use Example Data
                        </button>
                        <button
                            onClick={handleAnalyze}
                            disabled={isLoading}
                            className="w-full sm:w-auto px-8 py-3 bg-blue-600 hover:bg-blue-700 disabled:bg-blue-800 disabled:cursor-not-allowed rounded-md font-bold text-lg transition-all transform hover:scale-105 flex items-center justify-center space-x-2"
                        >
                            {isLoading ? (
                                <>
                                    <svg className="animate-spin -ml-1 mr-3 h-5 w-5 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                                        <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                                        <path className="opacity-75" fill="currentColor" d="M4 12a8 8 R 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                                    </svg>
                                    Analyzing...
                                </>
                            ) : (
                                "Get Media Buyer's Analysis"
                            )}
                        </button>
                    </div>
                    {error && <p className="text-red-400 mt-4 text-center">{error}</p>}
                </div>

                {summary && (
                    <div className="space-y-8">
                        <div>
                            <h2 className="text-3xl font-bold mb-6 text-blue-300 border-b-2 border-gray-700 pb-2">Dashboard</h2>
                            <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-5 gap-6">
                                <KpiCard title="Total Ad Spend" value={`$${summary.totalSpend.toFixed(2)}`} icon={<DollarSignIcon />} />
                                <KpiCard title="Overall ROAS" value={`${summary.overallROAS.toFixed(2)}x`} icon={<TargetIcon />} />
                                {audiencePerformance.length > 0 && <KpiCard title="Best Audience" value={bestAudience.name} subValue={bestAudience.value} icon={<UsersIcon />} />}
                                <KpiCard title="Total Impressions" value={summary.totalImpressions.toLocaleString()} icon={<EyeIcon />} />
                                <KpiCard title="Total Clicks" value={summary.totalClicks.toLocaleString()} icon={<PointerIcon />} />
                            </div>
                        </div>

                        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                           <div className="bg-gray-800 p-6 rounded-lg shadow-xl">
                                <h3 className="text-xl font-semibold mb-4 text-white">Spend vs ROAS by Campaign</h3>
                                <ResponsiveContainer width="100%" height={300}>
                                    <BarChart data={campaigns} margin={{ top: 5, right: 20, left: 20, bottom: 5 }}>
                                        <CartesianGrid strokeDasharray="3 3" stroke="#4A5568" />
                                        <XAxis dataKey="name" stroke="#A0AEC0" interval={0} angle={-20} textAnchor="end" height={60} />
                                        <YAxis yAxisId="left" orientation="left" stroke="#A0AEC0" />
                                        <YAxis yAxisId="right" orientation="right" stroke="#63B3ED" />
                                        <Tooltip contentStyle={{ backgroundColor: '#1A202C', border: '1px solid #4A5568' }} />
                                        <Legend />
                                        <Bar yAxisId="left" dataKey="spend" fill="#2B6CB0" name="Spend ($)" />
                                        <Bar yAxisId="right" dataKey="roas" fill="#63B3ED" name="ROAS" />
                                    </BarChart>
                                </ResponsiveContainer>
                            </div>
                           <div className="bg-gray-800 p-6 rounded-lg shadow-xl">
                                <h3 className="text-xl font-semibold mb-4 text-white">ROAS by Audience</h3>
                                 <ResponsiveContainer width="100%" height={300}>
                                     <BarChart data={audiencePerformance} layout="vertical" margin={{ top: 5, right: 30, left: 30, bottom: 5 }}>
                                        <CartesianGrid strokeDasharray="3 3" stroke="#4A5568" />
                                        <XAxis type="number" stroke="#A0AEC0" />
                                        <YAxis type="category" dataKey="audience" stroke="#A0AEC0" width={150} />
                                        <Tooltip contentStyle={{ backgroundColor: '#1A202C', border: '1px solid #4A5568' }} />
                                        <Legend />
                                        <Bar dataKey="roas" fill="#4FD1C5" name="ROAS" />
                                    </BarChart>
                                </ResponsiveContainer>
                            </div>
                        </div>

                        {recommendations && (
                            <div className="bg-gray-800 rounded-lg shadow-2xl p-6">
                                <div className="flex justify-between items-center border-b-2 border-gray-700 pb-2 mb-4">
                                    <h2 className="text-3xl font-bold text-blue-300">AI-Powered Strategic Recommendations</h2>
                                    <button 
                                        onClick={handleSendEmail}
                                        className="px-4 py-2 bg-indigo-600 hover:bg-indigo-700 rounded-md font-semibold transition-colors flex items-center space-x-2"
                                    >
                                        <SendIcon />
                                        <span>Send Report by Email</span>
                                    </button>
                                </div>
                                <div className="prose prose-invert max-w-none text-gray-300">{formattedRecommendations}</div>
                            </div>
                        )}
                    </div>
                )}
            </main>
        </div>
    );
};

