const DANGER_COLOR = '#e53e3e';
const SUCCESS_COLOR = '#38a169';
const TITLE_COLOR = '#63b3ed';
const BG_COLOR = '#1a202c';
const CARD_COLOR = '#2d3748';
const TEXT_COLOR = '#e2e8f0';
const BORDER_COLOR = '#4a5568';

const processLine = (line: string): string => {
    let styledLine = line;

    // Remove markdown-style bolding for HTML processing
    styledLine = styledLine.replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>');

    // Color-code specific keywords
    if (line.includes('KILL IT') || line.includes('🔪')) {
        return `<span style="color: ${DANGER_COLOR};">${styledLine}</span>`;
    }
    if (line.includes('SCALE IT') || line.includes('🚀')) {
        return `<span style="color: ${SUCCESS_COLOR};">${styledLine}</span>`;
    }
    return styledLine;
};

export const generateEmailHtml = (recommendations: string, summary: AnalysisSummary): string => {
    const sections: { [key: string]: string[] } = {};
    let currentSection = 'Introduction';
    sections[currentSection] = [];

    recommendations.split('\n').forEach(line => {
        if (line.startsWith('**') && line.endsWith('**')) {
            currentSection = line.replace(/\*\*/g, '');
            sections[currentSection] = [];
        } else if (line.trim() !== '') {
            sections[currentSection].push(line);
        }
    });

    let htmlSections = '';
    for (const title in sections) {
        if (sections[title].length > 0) {
            htmlSections += `
                <h3 style="color: ${TITLE_COLOR}; border-bottom: 1px solid ${BORDER_COLOR}; padding-bottom: 8px; margin-top: 24px;">${title}</h3>
                <ul style="list-style-type: none; padding-left: 0;">
                    ${sections[title].map(line => `<li style="padding: 4px 0;">${processLine(line)}</li>`).join('')}
                </ul>
            `;
        }
    }

    return `
    <!DOCTYPE html>
    <html lang="en">
    <head>
        <meta charset="UTF-8">
        <meta name="viewport" content="width=device-width, initial-scale=1.0">
        <title>Meta Ads Performance Analysis Report</title>
    </head>
    <body style="background-color: ${BG_COLOR}; color: ${TEXT_COLOR}; font-family: Arial, sans-serif; margin: 0; padding: 20px;">
        <table width="100%" border="0" cellspacing="0" cellpadding="0">
            <tr>
                <td align="center">
                    <table width="600" border="0" cellspacing="0" cellpadding="20" style="background-color: ${CARD_COLOR}; border-radius: 8px;">
                        <tr>
                            <td>
                                <h1 style="color: #ffffff; text-align: center;">Meta Ads Performance Report</h1>
                                <h2 style="color: ${TITLE_COLOR}; border-bottom: 1px solid ${BORDER_COLOR}; padding-bottom: 8px;">Overall Performance Summary</h2>
                                <p><strong>Total Ad Spend:</strong> $${summary.totalSpend.toFixed(2)}</p>
                                <p><strong>Overall ROAS:</strong> <span style="font-weight: bold; color: ${summary.overallROAS >= 3 ? SUCCESS_COLOR : DANGER_COLOR};">${summary.overallROAS.toFixed(2)}x</span></p>
                                <p><strong>Total Purchases:</strong> ${summary.totalPurchases.toLocaleString()}</p>

                                ${htmlSections}

                            </td>
                        </tr>
                    </table>
                </td>
            </tr>
        </table>
    </body>
    </html>
    `;
};

import { Campaign, AnalysisSummary } from '../types';

const getHeaderIndex = (headers: string[], possibleNames: string[]): number => {
    for (const name of possibleNames) {
        const index = headers.indexOf(name);
        if (index !== -1) return index;
    }
    return -1;
};

export const parseAndProcessData = (csvData: string): { campaigns: Campaign[], summary: AnalysisSummary } => {
    const lines = csvData.trim().split('\n');
    if (lines.length < 2) {
        throw new Error('CSV data must have at least one header row and one data row.');
    }

    const rawHeaders = lines[0].split(',').map(h => h.trim().toLowerCase());
    const dataRows = lines.slice(1);

    const headerMap = {
        name: getHeaderIndex(rawHeaders, ['campaign name', 'campaign', 'nom de la campagne']),
        spend: getHeaderIndex(rawHeaders, ['amount spent (usd)', 'spend', 'amount spent', 'budget dépensé']),
        impressions: getHeaderIndex(rawHeaders, ['impressions']),
        clicks: getHeaderIndex(rawHeaders, ['clicks', 'link clicks', 'clicks (all)']),
        purchases: getHeaderIndex(rawHeaders, ['purchases', 'conversions', 'achats']),
        roas: getHeaderIndex(rawHeaders, ['purchase roas (return on ad spend)', 'roas', 'roas (purchase)', 'roas (achats)']),
        audience: getHeaderIndex(rawHeaders, ['audience', 'audience name', "nom de l'audience"]),
    };

    const requiredHeaders: (keyof typeof headerMap)[] = ['name', 'spend', 'impressions', 'clicks', 'purchases', 'roas'];
    for (const key of requiredHeaders) {
        if (headerMap[key] === -1) {
            throw new Error(`Missing required CSV column: ${key}. Please check your data.`);
        }
    }


    const campaigns: Campaign[] = dataRows.map(row => {
        // Handle CSVs with commas inside quoted fields
        const values = row.split(/,(?=(?:(?:[^"]*"){2})*[^"]*$)/).map(v => v.replace(/"/g, ''));

        const name = values[headerMap.name]?.trim() || 'N/A';
        const spend = parseFloat(values[headerMap.spend]) || 0;
        const impressions = parseInt(values[headerMap.impressions], 10) || 0;
        const clicks = parseInt(values[headerMap.clicks], 10) || 0;
        const purchases = parseInt(values[headerMap.purchases], 10) || 0;
        const roas = parseFloat(values[headerMap.roas]) || 0;
        const audience = headerMap.audience > -1 ? values[headerMap.audience]?.trim() || 'N/A' : 'N/A';

        // Calculated metrics
        const ctr = impressions > 0 ? (clicks / impressions) * 100 : 0;
        const cpc = clicks > 0 ? spend / clicks : 0;
        const cpm = impressions > 0 ? (spend / impressions) * 1000 : 0;
        const cpp = purchases > 0 ? spend / purchases : 0;

        return { name, spend, impressions, clicks, purchases, roas, ctr, cpc, cpm, cpp, audience };
    }).filter(c => c.name && c.name !== 'N/A'); // Filter out empty rows

    if (campaigns.length === 0) {
        throw new Error('No valid campaign data could be parsed from the CSV.');
    }

    const summary: AnalysisSummary = campaigns.reduce((acc, campaign) => {
        acc.totalSpend += campaign.spend;
        acc.totalImpressions += campaign.impressions;
        acc.totalClicks += campaign.clicks;
        acc.totalPurchases += campaign.purchases;
        return acc;
    }, {
        totalSpend: 0,
        totalImpressions: 0,
        totalClicks: 0,
        totalPurchases: 0,
        overallROAS: 0,
        avgCTR: 0,
        avgCPC: 0,
        avgCPM: 0,
        avgCPP: 0
    });

    const totalRevenue = campaigns.reduce((sum, c) => sum + (c.spend * c.roas), 0);
    summary.overallROAS = summary.totalSpend > 0 ? totalRevenue / summary.totalSpend : 0;
    summary.avgCTR = summary.totalImpressions > 0 ? (summary.totalClicks / summary.totalImpressions) * 100 : 0;
    summary.avgCPC = summary.totalClicks > 0 ? summary.totalSpend / summary.totalClicks : 0;
    summary.avgCPM = summary.totalImpressions > 0 ? (summary.totalSpend / summary.totalImpressions) * 1000 : 0;
    summary.avgCPP = summary.totalPurchases > 0 ? summary.totalSpend / summary.totalPurchases : 0;

    return { campaigns, summary };
};

import { Campaign, AnalysisSummary } from '../types';

const getHeaderIndex = (headers: string[], possibleNames: string[]): number => {
    for (const name of possibleNames) {
        const index = headers.indexOf(name);
        if (index !== -1) return index;
    }
    return -1;
