import { Campaign, AnalysisSummary } from '../types';

const getHeaderIndex = (headers: string[], possibleNames: string[]): number => {
    for (const name of possibleNames) {
        // Find exact match or match for quoted header
        const index = headers.findIndex(h => h === name || h === `"${name}"`);
        if (index !== -1) return index;
    }
    return -1;
};

export const parseAndProcessData = (csvData: string): { campaigns: Campaign[], summary: AnalysisSummary } => {
    // Handle potential BOM character at the start of the file
    if (csvData.charCodeAt(0) === 0xFEFF) {
        csvData = csvData.substring(1);
    }

    const lines = csvData.trim().split('\n');
    if (lines.length < 2) {
        throw new Error('CSV data must have at least one header row and one data row.');
    }

    const headerLine = lines[0].trim();
    const delimiter = ','; // Facebook exports use comma, even with quotes

    const rawHeaders = headerLine.split(delimiter).map(h => h.trim().toLowerCase().replace(/^"|"$/g, ''));
    const dataRows = lines.slice(1);

    const headerMap = {
        name: getHeaderIndex(rawHeaders, ['campaign name', 'campaign', 'nom de la campagne']),
        spend: getHeaderIndex(rawHeaders, ['amount spent (usd)', 'spend', 'amount spent', 'budget dépensé', 'montant dépensé (usd)', 'montant dépensé (eur)']),
        impressions: getHeaderIndex(rawHeaders, ['impressions']),
        clicks: getHeaderIndex(rawHeaders, ['clicks', 'link clicks', 'clicks (all)', 'clics', 'clics sur un lien']),
        purchases: getHeaderIndex(rawHeaders, ['purchases', 'conversions', 'achats']),
        results: getHeaderIndex(rawHeaders, ['résultats', 'results']),
        resultType: getHeaderIndex(rawHeaders, ['type de résultat', 'result type']),
        roas: getHeaderIndex(rawHeaders, ['purchase roas (return on ad spend)', 'roas', 'roas (purchase)', 'roas (achats)', 'roas sur les achats (retour sur les dépenses publicitaires)']),
        audience: getHeaderIndex(rawHeaders, ['audience', 'audience name', "nom de l'audience", 'nom de l’ensemble de publicités']),
    };

    const requiredCoreHeaders: (keyof typeof headerMap)[] = ['name', 'spend', 'impressions', 'clicks'];
    for (const key of requiredCoreHeaders) {
        if (headerMap[key] === -1) {
            throw new Error(`Missing required CSV column: ${key}. Please check your data. Found headers: [${rawHeaders.join(', ')}]`);
        }
    }

    if (headerMap.purchases === -1 && (headerMap.results === -1 || headerMap.resultType === -1)) {
        throw new Error('Could not find purchase data. Ensure your CSV has a "purchases" column, or "results" and "result type" columns.');
    }

    const valueSplitRegex = new RegExp(`${delimiter}(?=(?:(?:[^"]*"){2})*[^"]*$)`);

    const campaigns: Campaign[] = dataRows.map(row => {
        if (!row.trim() || row.startsWith(',')) return null; // Skip empty lines and summary lines

        const values = row.split(valueSplitRegex).map(v => v.trim().replace(/^"|"$/g, ''));

        const name = values[headerMap.name]?.trim() || 'N/A';
        if (name === 'N/A' || name === '') return null;

        const spend = parseFloat(values[headerMap.spend]?.replace(',', '.')) || 0;
        const impressions = parseInt(values[headerMap.impressions], 10) || 0;
        const clicks = parseInt(values[headerMap.clicks], 10) || 0;

        let purchases = 0;
        if (headerMap.purchases > -1) {
            purchases = parseInt(values[headerMap.purchases], 10) || 0;
        } else if (headerMap.results > -1 && headerMap.resultType > -1) {
            const resultTypeValue = values[headerMap.resultType] || '';
            if (resultTypeValue.toLowerCase().includes('achat')) {
                purchases = parseInt(values[headerMap.results], 10) || 0;
            }
        }

        const roas = headerMap.roas > -1 ? (parseFloat(values[headerMap.roas]?.replace(',', '.')) || 0) : 0;
        const audience = headerMap.audience > -1 ? values[headerMap.audience]?.trim() || 'N/A' : 'N/A';

        // Calculated metrics
        const ctr = impressions > 0 ? (clicks / impressions) * 100 : 0;
        const cpc = clicks > 0 ? spend / clicks : 0;
        const cpm = impressions > 0 ? (spend / impressions) * 1000 : 0;
        const cpp = purchases > 0 ? spend / purchases : 0;

        return { name, spend, impressions, clicks, purchases, roas, ctr, cpc, cpm, cpp, audience };
    }).filter((c): c is Campaign => c !== null);

    if (campaigns.length === 0) {
        throw new Error('No valid campaign data could be parsed from the CSV.');
    }

    // Aggregate data by campaign name
    const campaignMap = new Map<string, Campaign>();
    campaigns.forEach(ad => {
        const campaign = campaignMap.get(ad.name) || {
            name: ad.name, spend: 0, impressions: 0, clicks: 0, purchases: 0, roas: 0, ctr: 0, cpc: 0, cpm: 0, cpp: 0, audience: 'Multiple'
        };
        campaign.spend += ad.spend;
        campaign.impressions += ad.impressions;
        campaign.clicks += ad.clicks;
        campaign.purchases += ad.purchases;
        // ROAS needs to be recalculated at the campaign level
        campaignMap.set(ad.name, campaign);
    });

    const aggregatedCampaigns = Array.from(campaignMap.values()).map(campaign => {
        const totalRevenue = campaigns
            .filter(ad => ad.name === campaign.name)
            .reduce((sum, ad) => sum + (ad.spend * ad.roas), 0);

        campaign.roas = campaign.spend > 0 ? totalRevenue / campaign.spend : 0;
        campaign.ctr = campaign.impressions > 0 ? (campaign.clicks / campaign.impressions) * 100 : 0;
        campaign.cpc = campaign.clicks > 0 ? campaign.spend / campaign.clicks : 0;
        campaign.cpm = campaign.impressions > 0 ? (campaign.spend / campaign.impressions) * 1000 : 0;
        campaign.cpp = campaign.purchases > 0 ? campaign.spend / campaign.purchases : 0;
        return campaign;
    });

    const summary: AnalysisSummary = aggregatedCampaigns.reduce((acc, campaign) => {
        acc.totalSpend += campaign.spend;
        acc.totalImpressions += campaign.impressions;
        acc.totalClicks += campaign.clicks;
        acc.totalPurchases += campaign.purchases;
        return acc;
    }, {
        totalSpend: 0,
        totalImpressions: 0,
        totalClicks: 0,
        totalPurchases: 0,
        overallROAS: 0,
        avgCTR: 0,
        avgCPC: 0,
        avgCPM: 0,
        avgCPP: 0
    });

    const totalRevenueGlobal = aggregatedCampaigns.reduce((sum, c) => sum + (c.spend * c.roas), 0);
    summary.overallROAS = summary.totalSpend > 0 ? totalRevenueGlobal / summary.totalSpend : 0;
    summary.avgCTR = summary.totalImpressions > 0 ? (summary.totalClicks / summary.totalImpressions) * 100 : 0;
    summary.avgCPC = summary.totalClicks > 0 ? summary.totalSpend / summary.totalClicks : 0;
    summary.avgCPM = summary.totalImpressions > 0 ? (summary.totalSpend / summary.totalImpressions) * 1000 : 0;
    summary.avgCPP = summary.totalPurchases > 0 ? summary.totalSpend / summary.totalPurchases : 0;

    return { campaigns: aggregatedCampaigns, summary };
};

import { GoogleGenAI, GenerateContentResponse } from "@google/genai";
import { Campaign, AnalysisSummary } from '../types';

export const getRecommendations = async (campaigns: Campaign[], summary: AnalysisSummary): Promise<string> => {
    if (!process.env.API_KEY) {
        throw new Error("API_KEY environment variable not set");
    }

    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    const hasAudienceData = campaigns.some(c => c.audience && c.audience !== 'N/A' && c.audience !== 'Multiple');
    const hasRoasData = summary.overallROAS > 0.01;

    const roasAnalysisBlock = `
**THE BOTTOM LINE:**
Start with a no-BS summary of the account's health. Is it making money or burning cash? What's the overall ROAS? Be direct.

**KILL OR SCALE: Campaign Breakdown**
*   **SCALE IT 🚀:** Identify the top 1-2 campaigns that are printing money (highest ROAS). Explain exactly WHY they are winning and give an aggressive scaling plan (e.g., "Crank up the budget by 30% now.").
*   **KILL IT 🔪:** Identify the 1-2 worst-performing campaigns that are bleeding money. Be ruthless. Tell the user to pause them immediately and explain why they're failing (e.g., "This campaign has a 1.5x ROAS. You're losing money. Shut it down yesterday.").
    `;

    const cppAnalysisBlock = `
**THE BOTTOM LINE (ROAS DATA UNAVAILABLE):**
ROAS data is missing, so I'm switching to a Cost-Per-Purchase (CPP) analysis. The game is about acquiring customers as cheaply as possible. Your average CPP is **€${summary.avgCPP.toFixed(2)}**. Let's see who's efficient and who's just burning cash.

**KILL OR SCALE: Campaign Breakdown**
*   **SCALE IT 🚀:** Identify the top 1-2 campaigns with the **LOWEST CPP**. These are your most efficient customer acquisition machines. Explain why they're working (likely a winning combo of creative and audience) and how to scale them.
*   **KILL IT 🔪:** Identify the 1-2 campaigns with the **HIGHEST CPP** or those spending significant money with zero purchases. These are budget vampires. Tell the user to kill them immediately.
    `;

    const prompt = `
        You are 'THE WOLF OF ADS', the world's greatest media buyer, known for turning ad spend into massive profits. Your advice is direct, brutally honest, and hyper-focused on scaling what works and killing what doesn't. You don't waste time on vanity metrics. You care about efficiency and profit.

        Analyze the following Meta Ads campaign data like a top-tier performance marketer. The currency is likely EUR based on the export.

        **Overall Summary:**
        ${JSON.stringify(summary, (key, value) => typeof value === 'number' ? value.toFixed(2) : value, 2)}

        **Performance by Campaign:**
        ${JSON.stringify(campaigns, (key, value) => typeof value === 'number' ? value.toFixed(2) : value, 2)}

        Provide your analysis in aggressive, actionable Markdown format. Use this structure:

        ${hasRoasData ? roasAnalysisBlock : cppAnalysisBlock}

        ${hasAudienceData ? `
        **GOLDMINE AUDIENCES:**
        This is where the real money is made.
        *   **Winning Audiences:** Pinpoint the exact audiences with the highest ROAS (or lowest CPP if ROAS is unavailable). Tell the user to double down on these.
        *   **Loser Audiences:** Pinpoint the audiences that are a waste of money. Tell the user to stop targeting them.
        *   **Alpha Insight:** Provide a key insight about their audiences. Are retargeting audiences carrying all the weight? Is a specific prospecting audience showing potential?
        ` : ''}

        **IMMEDIATE ACTION PLAN (Your Roadmap to Profit):**
        Give a numbered list of 3-5 high-impact, immediate actions. This is a direct order list.
        1.  **Budget Reallocation:** Be specific. "ACTION: Pause [Campaign X] immediately. Reallocate its entire daily budget to [Campaign Y] and [Campaign Z], splitting it 50/50."
        2.  **Audience & Targeting:** Be precise. "ACTION: The '[Audience Name]' is your goldmine. Create a new ad set targeting a 1% Lookalike Audience in your primary market based on these converters. Exclude recent purchasers."
        3.  **Creative Testing:** Give a clear testing instruction. "ACTION: The creative in your winning campaigns is working. Duplicate the ads from [Campaign Y] into a new ad set targeting your best Lookalike audience. Don't change a thing."
        4.  **Kill a Loser:** Reiterate the need to cut losses. "ACTION: I already told you to kill [Campaign X]. If you haven't done it yet, do it now. Stop wasting money."

        Your tone must be confident, expert, and laser-focused on maximizing profit. No fluff. Just actionable, money-making advice.
    `;

    try {
        const response: GenerateContentResponse = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: prompt,
        });
        return response.text;
    } catch (error) {
        console.error("Error calling Gemini API:", error);
        throw new Error("Failed to get recommendations from AI. Please check the API key and try again.");
    }
};

