import React, { useState, useMemo } from 'react';
import { Campaign } from '../types';

type SortConfig = {
    key: keyof Campaign;
    direction: 'ascending' | 'descending';
} | null;

interface CampaignTableProps {
    campaigns: Campaign[];
    translations: Record<string, string>;
}

const Tooltip: React.FC<{ text: string; children: React.ReactNode }> = ({ text, children }) => (
    <div className="group relative flex items-center">
        {children}
        <div className="absolute left-1/2 -translate-x-1/2 bottom-full mb-2 w-48 bg-gray-900 text-white text-xs rounded-lg p-2 opacity-0 group-hover:opacity-100 transition-opacity duration-300 pointer-events-none shadow-lg z-10">
            {text}
        </div>
    </div>
);

const SortableHeader: React.FC<{
    title: string;
    tooltipText: string;
    sortKey: keyof Campaign;
    sortConfig: SortConfig;
    requestSort: (key: keyof Campaign) => void;
}> = ({ title, tooltipText, sortKey, sortConfig, requestSort }) => {
    const isSorted = sortConfig?.key === sortKey;
    const directionIcon = isSorted ? (sortConfig.direction === 'ascending' ? '▲' : '▼') : '';

    return (
        <th
            className="p-3 text-left text-xs font-medium text-gray-300 uppercase tracking-wider cursor-pointer hover:bg-gray-700"
            onClick={() => requestSort(sortKey)}
        >
            <Tooltip text={tooltipText}>
                <div className="flex items-center">
                    {title} <span className="ml-1">{directionIcon}</span>
                </div>
            </Tooltip>
        </th>
    );
};


export const CampaignTable: React.FC<CampaignTableProps> = ({ campaigns, translations: t }) => {
    const [filterText, setFilterText] = useState('');
    const [sortConfig, setSortConfig] = useState<SortConfig>({ key: 'spend', direction: 'descending' });

    const filteredCampaigns = useMemo(() => {
        return campaigns.filter(c => c.name.toLowerCase().includes(filterText.toLowerCase()));
    }, [campaigns, filterText]);

    const sortedCampaigns = useMemo(() => {
        let sortableItems = [...filteredCampaigns];
        if (sortConfig !== null) {
            sortableItems.sort((a, b) => {
                if (a[sortConfig.key] < b[sortConfig.key]) {
                    return sortConfig.direction === 'ascending' ? -1 : 1;
                }
                if (a[sortConfig.key] > b[sortConfig.key]) {
                    return sortConfig.direction === 'ascending' ? 1 : -1;
                }
                return 0;
            });
        }
        return sortableItems;
    }, [filteredCampaigns, sortConfig]);

    const requestSort = (key: keyof Campaign) => {
        let direction: 'ascending' | 'descending' = 'descending';
        if (sortConfig && sortConfig.key === key && sortConfig.direction === 'descending') {
            direction = 'ascending';
        }
        setSortConfig({ key, direction });
    };

    const headers: { key: keyof Campaign; title: string; tooltip: string; }[] = [
        { key: 'spend', title: `${t.spendLabel} (€)`, tooltip: t.tooltipSpend },
        { key: 'impressions', title: t.kpiImpressions, tooltip: t.tooltipImpressions },
        { key: 'clicks', title: t.kpiClicks, tooltip: t.tooltipClicks },
        { key: 'ctr', title: 'CTR (%)', tooltip: t.tooltipCTR },
        { key: 'cpc', title: 'CPC (€)', tooltip: t.tooltipCPC },
        { key: 'purchases', title: 'Purchases', tooltip: t.tooltipPurchases },
        { key: 'roas', title: 'ROAS', tooltip: t.tooltipROAS },
        { key: 'cpp', title: `${t.cppLabel} (€)`, tooltip: t.tooltipCPP },
    ];


    return (
        <div className="bg-gray-800 p-4 sm:p-6 rounded-lg shadow-xl">
            <div className="flex flex-col sm:flex-row justify-between items-center mb-4">
                <h3 className="text-xl font-semibold text-white mb-4 sm:mb-0">{t.chartCampaignTitle}</h3>
                <input
                    type="text"
                    placeholder={t.filterPlaceholder}
                    value={filterText}
                    onChange={(e) => setFilterText(e.target.value)}
                    className="w-full sm:w-64 p-2 bg-gray-900 border border-gray-600 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                />
            </div>
            <div className="overflow-x-auto">
                <table className="min-w-full divide-y divide-gray-700">
                    <thead className="bg-gray-900/50">
                        <tr>
                            <th className="p-3 text-left text-xs font-medium text-gray-300 uppercase tracking-wider">Campaign</th>
                            {headers.map(header => (
                               <SortableHeader
                                   key={header.key}
                                   title={header.title}
                                   tooltipText={header.tooltip}
                                   sortKey={header.key}
                                   sortConfig={sortConfig}
                                   requestSort={requestSort}
                                />
                            ))}
                        </tr>
                    </thead>
                    <tbody className="bg-gray-800 divide-y divide-gray-700">
                        {sortedCampaigns.map(campaign => (
                            <tr key={campaign.name} className="hover:bg-gray-700/50">
                                <td className="p-3 whitespace-nowrap text-sm font-medium text-white">{campaign.name}</td>
                                <td className="p-3 whitespace-nowrap text-sm text-gray-300">€{campaign.spend.toFixed(2)}</td>
                                <td className="p-3 whitespace-nowrap text-sm text-gray-300">{campaign.impressions.toLocaleString()}</td>
                                <td className="p-3 whitespace-nowrap text-sm text-gray-300">{campaign.clicks.toLocaleString()}</td>
                                <td className="p-3 whitespace-nowrap text-sm text-gray-300">{campaign.ctr.toFixed(2)}%</td>
                                <td className="p-3 whitespace-nowrap text-sm text-gray-300">€{campaign.cpc.toFixed(2)}</td>
                                <td className="p-3 whitespace-nowrap text-sm text-gray-300">{campaign.purchases.toLocaleString()}</td>
                                <td className="p-3 whitespace-nowrap text-sm text-gray-300">{campaign.roas.toFixed(2)}x</td>
                                <td className="p-3 whitespace-nowrap text-sm text-gray-300">€{campaign.cpp.toFixed(2)}</td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>
        </div>
    );
};

