"ZONE NEW","Mix 1","Nouvelle publicité de Ventes","Nouvelle publicité de Ventes",active,ad,8953,11804,1.31844075,"Achats sur le site Web",9,1.75111111,15.76,2025-12-01,"En cours",1.33514063,765,0.02060131,6.48085395,,2025-12-21,2025-12-21
"U-falcon","Flexible","6","6",active,ad,16109,19286,1.19721895,"Achats sur le site Web",2,5.45,10.9,2025-12-18,"En cours",0.56517681,802,0.01359102,4.15845691,,2025-12-21,2025-12-21
"IZZY test","Flexible","Nouvelle publicité de Ventes","Nouvelle publicité de Ventes",active,ad,21396,24941,1.16568517,"Achats sur le site Web",6,1.38833333,8.33,2025-12-20,"En cours",0.33398821,314,0.02652866,1.25897117,,2025-12-21,2025-12-21
"Peak","Nouvel ensemble de publicités de Ventes","Nouvelle publicité de Ventes","Nouvelle publicité de Ventes",active,ad,15320,15884,1.03681462,"Achats sur le site Web",1,7.77,7.77,2025-12-03,"En cours",0.48917149,166,0.04680723,1.04507681,,2025-12-21,2025-12-21
"Optimus New","Nouvel ensemble de publicités de Ventes","Nouvelle publicité de Ventes","Nouvelle publicité de Ventes",active,ad,9836,10737,1.09160228,"Achats sur le site Web",6,1.285,7.71,2025-12-20,"En cours",0.71807768,243,0.0317284,2.26320201,,2025-12-21,2025-12-21
"3 bande Jdida (F5) - Copie","Nouvel ensemble de publicités de Ventes","Nouvelle publicité de Ventes","Nouvelle publicité de Ventes",active,ad,5333,6873,1.28876805,"Achats sur le site Web",2,3.805,7.61,2025-12-03,"En cours",1.10723119,226,0.03367257,3.2882293,,2025-12-21,2025-12-21
"RB Pro","Nouvel ensemble de publicités de Ventes","Nouvelle publicité de Ventes","Nouvelle publicité de Ventes",active,ad,14183,16829,1.18656138,"Achats sur le site Web",22,0.34590909,7.61,2025-09-04,"En cours",0.45219561,501,0.01518962,2.97700398,,2025-12-21,2025-12-21
`;

    const handleUseExample = () => {
        setCsvData(exampleCSV);
        setFileName('export_meta_ads_detailed_fr.csv');
        setError('');
    };

    const audiencePerformance = useMemo(() => {
        if (campaigns.length === 0) return [];
        const audienceMap = new Map<string, { totalSpend: number; totalPurchases: number; totalRevenue: number }>();
        try {
            const { campaigns: rawCampaigns } = parseAndProcessData(csvData); 
            rawCampaigns.forEach(campaign => {
                 if (campaign.audience && campaign.audience !== 'N/A') {
                    const stats = audienceMap.get(campaign.audience) || { totalSpend: 0, totalPurchases: 0, totalRevenue: 0 };
                    stats.totalSpend += campaign.spend;
                    stats.totalPurchases += campaign.purchases;
                    stats.totalRevenue += campaign.spend * campaign.roas;
                    audienceMap.set(campaign.audience, stats);
                }
            });
        } catch (e) { return []; }

        const performanceData = Array.from(audienceMap.entries()).map(([audience, stats]) => ({
            audience,
            roas: stats.totalSpend > 0 ? stats.totalRevenue / stats.totalSpend : 0,
            cpp: stats.totalPurchases > 0 ? stats.totalSpend / stats.totalPurchases : 0,
            spend: stats.totalSpend
        }));

        if (summary && summary.overallROAS < 0.01) {
            return performanceData.filter(a => a.cpp > 0).sort((a, b) => a.cpp - b.cpp);
        }
        return performanceData.sort((a, b) => b.roas - a.roas);

    }, [campaigns, summary, csvData]);

    const bestAudience = useMemo(() => {
        if (audiencePerformance.length === 0) return { name: 'N/A', value: 'N/A' };
        const topAudience = audiencePerformance[0];
        if (summary && summary.overallROAS < 0.01) {
             return { name: topAudience.audience, value: `€${topAudience.cpp.toFixed(2)} CPP` };
        }
        return { name: topAudience.audience, value: `${topAudience.roas.toFixed(2)}x ROAS` };
    }, [audiencePerformance, summary]);


    const formattedRecommendations = useMemo(() => {
        if (!recommendations) return null;
        return recommendations
            .split('\n')
            .map((line, index) => {
                if (line.startsWith('**')) return <h3 key={index} className="text-xl font-bold mt-4 mb-2 text-blue-400">{line.replace(/\*\*/g, '')}</h3>;
                if (line.startsWith('*   **')) return <li key={index} className="ml-6 list-disc" dangerouslySetInnerHTML={{ __html: line.substring(2).replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>') }}></li>;
                if (line.startsWith('* ')) return <li key={index} className="ml-6 list-disc">{line.substring(2)}</li>;
                if (/^\d+\./.test(line)) return <li key={index} className="ml-6 my-1" dangerouslySetInnerHTML={{ __html: line.replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>') }}></li>;
                return <p key={index} className="my-1">{line}</p>;
            });
    }, [recommendations]);

    const handleSendEmail = () => {
        if (!recommendations || !summary) return;
        const emailBody = generateEmailHtml(recommendations, summary);
        const subject = "Meta Ads Performance Analysis Report";
        window.location.href = `mailto:?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(emailBody)}`;
    };

    const handleExportPdf = async () => {
        if (!summary) return;
        setIsExporting(true);
        try {
            const { default: jsPDF } = await import('jspdf');
            const { default: html2canvas } = await import('html2canvas');

            const audienceChartEl = document.getElementById('audience-chart-container');
            if (!audienceChartEl) { throw new Error("Audience chart element not found for export."); }

            const audienceCanvas = await html2canvas(audienceChartEl, { backgroundColor: '#1f2937', scale: 2 });
            const audienceImgData = audienceCanvas.toDataURL('image/png');

            const pdf = new jsPDF('p', 'mm', 'a4');
            const pdfWidth = pdf.internal.pageSize.getWidth();
            const margin = 15;
            let yPos = margin;

            pdf.setTextColor('#e2e8f0');
            pdf.setFont('helvetica', 'bold');
            pdf.setFontSize(20);
            pdf.text(t.title, pdfWidth / 2, yPos, { align: 'center' });
            yPos += 15;

            pdf.setFontSize(16);
            pdf.text(t.dashboardTitle, margin, yPos);
            yPos += 8;

            pdf.setFont('helvetica', 'normal');
            pdf.setFontSize(11);
            pdf.text(`${t.kpiSpend}: €${summary.totalSpend.toFixed(2)}`, margin, yPos);
            pdf.text(`${summary.overallROAS > 0.01 ? `${t.kpiRoas}: ${summary.overallROAS.toFixed(2)}x` : `${t.kpiCpp}: €${summary.avgCPP.toFixed(2)}`}`, pdfWidth / 2, yPos, { align: 'center' });
            pdf.text(`${t.kpiImpressions}: ${summary.totalImpressions.toLocaleString()}`, pdfWidth - margin, yPos, { align: 'right' });
            yPos += 12;

            pdf.setFont('helvetica', 'bold');
            pdf.setFontSize(14);
            pdf.text(t.chartCampaignTitle, margin, yPos);
            yPos += 6;

            const tableData = campaigns.map(c => [
                c.name, `€${c.spend.toFixed(2)}`, c.impressions.toLocaleString(), c.clicks.toLocaleString(), `${c.ctr.toFixed(2)}%`, `€${c.cpc.toFixed(2)}`, c.purchases.toLocaleString(), `${c.roas.toFixed(2)}x`, `€${c.cpp.toFixed(2)}`
            ]);

            (pdf as any).autoTable({
                startY: yPos,
                head: [['Campaign', 'Spend', 'Impr.', 'Clicks', 'CTR', 'CPC', 'Purch.', 'ROAS', 'CPP']],
                body: tableData,
                theme: 'grid',
                headStyles: { fillColor: [41, 51, 65] },
                styles: { textColor: [226, 232, 240], cellPadding: 2 },
                columnStyles: { 0: { cellWidth: 45 } },
                didDrawPage: (data: any) => { yPos = data.cursor.y; }
            });
            yPos += 10;

            if (pdf.internal.pageSize.getHeight() - yPos < 80) { pdf.addPage(); yPos = margin; }

            const audImgHeight = (audienceCanvas.height * (pdfWidth - margin * 2)) / audienceCanvas.width;
            pdf.addImage(audienceImgData, 'PNG', margin, yPos, pdfWidth - margin * 2, audImgHeight);
            yPos += audImgHeight + 10;

            if (recommendations) {
                if (pdf.internal.pageSize.getHeight() - yPos < 40) { pdf.addPage(); yPos = margin; }
                pdf.setFont('helvetica', 'bold');
                pdf.setFontSize(16);
                pdf.text(t.recommendationsTitle, margin, yPos);
                yPos += 10;
                pdf.setFont('helvetica', 'normal');
                pdf.setFontSize(10);
                const splitText = pdf.splitTextToSize(recommendations.replace(/(\*\*|🚀|🔪)/g, ''), pdfWidth - margin * 2);
                splitText.forEach((line: string) => {
                    if (yPos > pdf.internal.pageSize.getHeight() - margin) { pdf.addPage(); yPos = margin; }
                    pdf.text(line, margin, yPos);
                    yPos += 5;
                });
            }
            pdf.save('meta-ads-report.pdf');
        } catch (err) {
            console.error("PDF export failed:", err);
            setError("PDF export failed. Please try again.");
        } finally {
            setIsExporting(false);
        }
    };


    return (
        <div className="min-h-screen bg-gray-900 text-gray-100 font-sans" dir={language === 'ar' ? 'rtl' : 'ltr'}>
            <header className="bg-gray-800/50 backdrop-blur-sm shadow-lg p-4 sticky top-0 z-10">
                <div className="container mx-auto flex justify-between items-center">
                    <h1 className="text-xl md:text-2xl font-bold text-white">{t.title}</h1>
                     <div className="flex items-center space-x-2 bg-gray-900 p-1 rounded-lg">
                        {(['fr', 'en', 'ar'] as Language[]).map(lang => (
                            <button key={lang} onClick={() => setLanguage(lang)} className={`px-3 py-1 text-sm font-semibold rounded-md transition-colors ${language === lang ? 'bg-blue-600 text-white' : 'text-gray-300 hover:bg-gray-700'}`}>{lang.toUpperCase()}</button>
                        ))}
                    </div>
                </div>
            </header>

            <main className="container mx-auto p-4 md:p-8">
                <div className="bg-gray-800 rounded-lg shadow-2xl p-6 mb-8">
                    <h2 className="text-2xl font-semibold mb-4 text-blue-300">{t.uploadTitle}</h2>
                    <div className="flex flex-col items-center justify-center w-full mt-4">
                        <label htmlFor="csv-upload" className="flex flex-col items-center justify-center w-full h-48 border-2 border-gray-600 border-dashed rounded-lg cursor-pointer bg-gray-900 hover:bg-gray-700 transition-colors">
                            <div className="flex flex-col items-center justify-center pt-5 pb-6 text-center">
                                <UploadIcon />
                                 {fileName ? ( <p className="font-semibold text-green-400">{fileName}</p> ) : (
                                    <>
                                        <p className="mb-2 text-sm text-gray-400"><span className="font-semibold">{t.uploadClick}</span> {t.uploadDrag}</p>
                                        <p className="text-xs text-gray-500">{t.uploadHint}</p>
                                    </>
                                )}
                            </div>
                            <input id="csv-upload" type="file" className="hidden" accept=".csv, text/csv" onChange={handleFileChange} />
                        </label>
                    </div>

                    <div className="flex flex-col sm:flex-row items-center justify-between mt-6 space-y-4 sm:space-y-0 sm:space-x-4">
                        <button onClick={handleUseExample} className="w-full sm:w-auto px-6 py-2 bg-gray-700 hover:bg-gray-600 rounded-md font-semibold transition-colors">{t.exampleButton}</button>
                        <div className="flex items-center space-x-4 flex-grow justify-end">
                             <div className="group relative flex items-center justify-center">
                                <div onClick={() => setIsThinkingMode(!isThinkingMode)} className="flex items-center space-x-2 cursor-pointer p-2 rounded-lg hover:bg-gray-700">
                                    <NetworkIntelligenceIcon />
                                    <span className="font-semibold text-gray-300">{t.thinkingMode}</span>
                                    <div className={`w-10 h-5 flex items-center rounded-full transition-colors ${isThinkingMode ? 'bg-blue-600' : 'bg-gray-600'}`}><div className={`w-4 h-4 bg-white rounded-full mx-0.5 transform transition-transform ${isThinkingMode ? 'translate-x-5' : ''}`}></div></div>
                                </div>
                                <div className="absolute bottom-full mb-2 w-64 bg-gray-900 text-white text-xs rounded-lg p-2 opacity-0 group-hover:opacity-100 transition-opacity duration-300 pointer-events-none shadow-lg">{t.thinkingModeTooltip}</div>
                            </div>
                            <button onClick={handleAnalyze} disabled={isLoading} className="w-full sm:w-auto px-8 py-3 bg-blue-600 hover:bg-blue-700 disabled:bg-blue-800 disabled:cursor-not-allowed rounded-md font-bold text-lg transition-all transform hover:scale-105 flex items-center justify-center space-x-2">
                                {isLoading ? ( <><svg className="animate-spin -ml-1 mr-3 h-5 w-5 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg>{t.analyzingButton}</> ) : ( t.analyzeButton )}
                            </button>
                        </div>
                    </div>
                    {error && <p className="text-red-400 mt-4 text-center">{error}</p>}
                </div>

                {summary && (
                    <div id="analysis-report" className="space-y-8">
                        <div className="bg-gray-800 rounded-lg shadow-2xl p-6">
                            <h2 className="text-3xl font-bold mb-6 text-blue-300 border-b-2 border-gray-700 pb-2">{t.dashboardTitle}</h2>
                            <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-5 gap-6">
                                <KpiCard title={t.kpiSpend} value={`€${summary.totalSpend.toFixed(2)}`} icon={<DollarSignIcon />} />
                                {summary.overallROAS > 0.01 ? <KpiCard title={t.kpiRoas} value={`${summary.overallROAS.toFixed(2)}x`} icon={<TargetIcon />} /> : <KpiCard title={t.kpiCpp} value={`€${summary.avgCPP.toFixed(2)}`} icon={<TargetIcon />} /> }
                                {audiencePerformance.length > 0 && <KpiCard title={t.kpiAudience} value={bestAudience.name} subValue={bestAudience.value} icon={<UsersIcon />} />}
                                <KpiCard title={t.kpiImpressions} value={summary.totalImpressions.toLocaleString()} icon={<EyeIcon />} />
                                <KpiCard title={t.kpiClicks} value={summary.totalClicks.toLocaleString()} icon={<PointerIcon />} />
                            </div>
                        </div>

                        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
                           <div className="lg:col-span-2">
                                <CampaignTable campaigns={campaigns} translations={t} />
                           </div>
                           <div id="audience-chart-container" className="bg-gray-800 p-6 rounded-lg shadow-xl">
                                <h3 className="text-xl font-semibold mb-4 text-white">{t.chartAudienceTitle}</h3>
                                 <ResponsiveContainer width="100%" height={400}>
                                     <BarChart data={audiencePerformance} layout="vertical" margin={{ top: 5, right: 30, left: 30, bottom: 5 }}>
                                        <CartesianGrid strokeDasharray="3 3" stroke="#4A5568" />
                                        <XAxis type="number" stroke="#A0AEC0" />
                                        <YAxis type="category" dataKey="audience" stroke="#A0AEC0" width={150} tick={{ fontSize: 12 }} />
                                        <Tooltip contentStyle={{ backgroundColor: '#1A202C', border: '1px solid #4A5568' }} formatter={(value: number) => value.toFixed(2)} />
                                        <Legend />
                                         {summary.overallROAS > 0.01 ? <Bar dataKey="roas" fill="#63B3ED" name={t.roasLabel} /> : <Bar dataKey="cpp" fill="#4FD1C5" name={`${t.cppLabel} (€)`} />}
                                    </BarChart>
                                </ResponsiveContainer>
                            </div>
                        </div>

                        {recommendations && (
                            <div className="bg-gray-800 rounded-lg shadow-2xl p-6">
                                <div className="flex justify-between items-center border-b-2 border-gray-700 pb-2 mb-4">
                                    <h2 className="text-3xl font-bold text-blue-300">{t.recommendationsTitle}</h2>
                                    <div className="flex items-center space-x-3">
                                        <button onClick={handleSendEmail} className="px-4 py-2 bg-indigo-600 hover:bg-indigo-700 rounded-md font-semibold transition-colors flex items-center space-x-2"><SendIcon /><span>{t.sendEmailButton}</span></button>
                                        <button onClick={handleExportPdf} disabled={isExporting} className="px-4 py-2 bg-green-600 hover:bg-green-700 disabled:bg-green-800 rounded-md font-semibold transition-colors flex items-center space-x-2"><DownloadIcon /><span>{isExporting ? t.exportingPdfButton : t.exportPdfButton}</span></button>
                                    </div>
                                </div>
                                <div id="recommendations-container" className="prose prose-invert max-w-none text-gray-300">{formattedRecommendations}</div>
                            </div>
                        )}
                    </div>
                )}
            </main>
        </div>
    );
};

export default App;

import React from 'react';
import { ResponsiveContainer, Treemap, Tooltip } from 'recharts';
import { Campaign } from '../types';

interface SpendTreemapProps {
    data: Campaign[];
    translations: Record<string, string>;
}

const getHexColor = (roas: number, hasRoasData: boolean) => {
    if (!hasRoasData) {
        return '#4A5568'; // gray-600
    }
    if (roas > 4) return '#2F855A'; // green-700 (Excellent)
    if (roas > 2.5) return '#38A169'; // green-600 (Good)
    if (roas > 1) return '#D69E2E'; // yellow-600 (Okay)
    return '#C53030'; // red-700 (Bad)
};

const CustomizedContent: React.FC<any> = ({ root, depth, x, y, width, height, index, name, roas }) => {
    const hasRoasData = roas > 0.01;
    return (
        <g>
            <rect
                x={x}
                y={y}
                width={width}
                height={height}
                style={{
                    fill: getHexColor(roas, hasRoasData),
                    stroke: '#1a202c',
                    strokeWidth: 2,
                    strokeOpacity: 1,
                }}
            />
            {width > 80 && height > 40 && (
                <text x={x + width / 2} y={y + height / 2 + 7} textAnchor="middle" fill="#fff" fontSize={14} fontWeight="bold">
                    {name}
                </text>
            )}
        </g>
    );
};

const CustomTooltip: React.FC<any> = ({ active, payload, translations: t }) => {
    if (active && payload && payload.length) {
        const data = payload[0].payload;
        return (
            <div className="bg-gray-900/80 p-3 rounded-md border border-gray-600 shadow-lg">
                <p className="font-bold text-white">{data.name}</p>
                <p className="text-blue-300">{`${t.spendLabel}: €${data.spend.toFixed(2)}`}</p>
                {data.roas > 0.01 ? (
                   <p className="text-green-400">{`${t.roasLabel}: ${data.roas.toFixed(2)}x`}</p>
                ) : (
                   <p className="text-teal-400">{`${t.cppLabel}: €${data.cpp.toFixed(2)}`}</p>
                )}
            </div>
        );
    }
    return null;
};


export const SpendTreemap: React.FC<SpendTreemapProps> = ({ data, translations }) => {
    const hasRoasData = data.some(c => c.roas > 0.01);

    return (
        <div className="bg-gray-800 p-6 rounded-lg shadow-xl h-full">
            <h3 className="text-xl font-semibold mb-4 text-white">{translations.spendDistributionTitle}</h3>
            <ResponsiveContainer width="100%" height={400}>
                <Treemap
                    data={data.filter(d => d.spend > 0)}
                    dataKey="spend"
                    ratio={4 / 3}
                    stroke="#fff"
                    fill="#8884d8"
                    content={<CustomizedContent />}
                    isAnimationActive={false}
                >
                    <Tooltip content={<CustomTooltip translations={translations}/>} />
                </Treemap>
            </ResponsiveContainer>
        </div>
    );
};

import React, { useState, useCallback, useMemo } from 'react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer } from 'recharts';
import { KpiCard } from './components/KpiCard';
import { Campaign, AnalysisSummary } from './types';
import { parseAndProcessData } from './utils/dataProcessor';
import { getRecommendations } from './services/geminiService';
import { DollarSignIcon, TargetIcon, EyeIcon, PointerIcon, UsersIcon, UploadIcon, SendIcon, NetworkIntelligenceIcon, DownloadIcon } from './components/icons';
import { generateEmailHtml } from './utils/emailGenerator';
import { translations } from './i18n/translations';
import { CampaignTable } from './components/CampaignTable';
import { SpendTreemap } from './components/SpendTreemap';
import { jsPDF } from 'jspdf';
import html2canvas from 'html2canvas';
import 'jspdf-autotable';

type Language = 'en' | 'fr' | 'ar';

const App: React.FC = () => {
    const [csvData, setCsvData] = useState<string>('');
    const [fileName, setFileName] = useState<string>('');
    const [campaigns, setCampaigns] = useState<Campaign[]>([]);
    const [summary, setSummary] = useState<AnalysisSummary | null>(null);
    const [recommendations, setRecommendations] = useState<string>('');
    const [isLoading, setIsLoading] = useState<boolean>(false);
    const [error, setError] = useState<string>('');
    const [language, setLanguage] = useState<Language>('fr');
    const [isThinkingMode, setIsThinkingMode] = useState<boolean>(false);
    const [isExporting, setIsExporting] = useState<boolean>(false);

    const t = useMemo(() => translations[language], [language]);

    const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
        const file = event.target.files?.[0];
        if (file) {
            setFileName(file.name);
            const reader = new FileReader();
            reader.onload = (e) => {
                const text = e.target?.result;
                if (typeof text === 'string') {
                    setCsvData(text);
                    setError('');
                } else {
                    setError(t.errorFileRead);
                }
            };
            reader.onerror = () => {
                setError(t.errorFileRead2);
            };
            reader.readAsText(file);
        }
    };

    const handleAnalyze = useCallback(async () => {
        if (!csvData.trim()) {
            setError(t.errorNoData);
            return;
        }
        setIsLoading(true);
        setError('');
        setRecommendations('');
        setCampaigns([]);
        setSummary(null);

        try {
            const { campaigns: parsedCampaigns, summary: analysisSummary } = parseAndProcessData(csvData);
            setCampaigns(parsedCampaigns);
            setSummary(analysisSummary);

            const aiRecommendations = await getRecommendations(parsedCampaigns, analysisSummary, language, isThinkingMode);
            setRecommendations(aiRecommendations);

        } catch (e: any) {
            setError(`${t.errorAnalysisFailed} ${e.message}`);
            console.error(e);
        } finally {
            setIsLoading(false);
        }
    }, [csvData, language, t, isThinkingMode]);

    const exampleCSV = `
