                <div className="container mx-auto flex justify-between items-center">
                    <h1 className="text-xl md:text-2xl font-bold text-white">{t.title}</h1>
                     <div className="flex items-center space-x-2 bg-gray-900 p-1 rounded-lg">
                        {(['fr', 'en', 'ar'] as Language[]).map(lang => (
                            <button key={lang} onClick={() => setLanguage(lang)} className={`px-3 py-1 text-sm font-semibold rounded-md transition-colors ${language === lang ? 'bg-blue-600 text-white' : 'text-gray-300 hover:bg-gray-700'}`}>{lang.toUpperCase()}</button>
                        ))}
                    </div>
                </div>
            </header>

            <main className="container mx-auto p-4 md:p-8">
                <div className="bg-gray-800 rounded-lg shadow-2xl p-6 mb-8">
                    <h2 className="text-2xl font-semibold mb-4 text-blue-300">{t.uploadTitle}</h2>
                    <div className="flex flex-col items-center justify-center w-full mt-4">
                        <label htmlFor="csv-upload" className="flex flex-col items-center justify-center w-full h-48 border-2 border-gray-600 border-dashed rounded-lg cursor-pointer bg-gray-900 hover:bg-gray-700 transition-colors">
                            <div className="flex flex-col items-center justify-center pt-5 pb-6 text-center">
                                <UploadIcon />
                                 {fileName ? ( <p className="font-semibold text-green-400">{fileName}</p> ) : (
                                    <>
                                        <p className="mb-2 text-sm text-gray-400"><span className="font-semibold">{t.uploadClick}</span> {t.uploadDrag}</p>
                                        <p className="text-xs text-gray-500">{t.uploadHint}</p>
                                    </>
                                )}
                            </div>
                            <input id="csv-upload" type="file" className="hidden" accept=".csv, text/csv" onChange={handleFileChange} />
                        </label>
                    </div>

                    <div className="flex flex-col sm:flex-row items-center justify-between mt-6 space-y-4 sm:space-y-0 sm:space-x-4">
                        <button onClick={handleUseExample} className="w-full sm:w-auto px-6 py-2 bg-gray-700 hover:bg-gray-600 rounded-md font-semibold transition-colors">{t.exampleButton}</button>
                        <div className="flex items-center space-x-4 flex-grow justify-end">
                             <div className="group relative flex items-center justify-center">
                                <div onClick={() => setIsThinkingMode(!isThinkingMode)} className="flex items-center space-x-2 cursor-pointer p-2 rounded-lg hover:bg-gray-700">
                                    <NetworkIntelligenceIcon />
                                    <span className="font-semibold text-gray-300">{t.thinkingMode}</span>
                                    <div className={`w-10 h-5 flex items-center rounded-full transition-colors ${isThinkingMode ? 'bg-blue-600' : 'bg-gray-600'}`}><div className={`w-4 h-4 bg-white rounded-full mx-0.5 transform transition-transform ${isThinkingMode ? 'translate-x-5' : ''}`}></div></div>
                                </div>
                                <div className="absolute bottom-full mb-2 w-64 bg-gray-900 text-white text-xs rounded-lg p-2 opacity-0 group-hover:opacity-100 transition-opacity duration-300 pointer-events-none shadow-lg">{t.thinkingModeTooltip}</div>
                            </div>
                            <button onClick={handleAnalyze} disabled={isLoading} className="w-full sm:w-auto px-8 py-3 bg-blue-600 hover:bg-blue-700 disabled:bg-blue-800 disabled:cursor-not-allowed rounded-md font-bold text-lg transition-all transform hover:scale-105 flex items-center justify-center space-x-2">
                                {isLoading ? ( <><svg className="animate-spin -ml-1 mr-3 h-5 w-5 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg>{t.analyzingButton}</> ) : ( t.analyzeButton )}
                            </button>
                        </div>
                    </div>
                    {error && <p className="text-red-400 mt-4 text-center">{error}</p>}
                </div>

                {summary && (
                    <div id="analysis-report" className="space-y-8">
                        <div id="kpi-container" className="bg-gray-800 rounded-lg shadow-2xl p-6">
                            <h2 className="text-3xl font-bold mb-6 text-blue-300 border-b-2 border-gray-700 pb-2">{t.dashboardTitle}</h2>
                            <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-5 gap-6">
                                <KpiCard title={t.kpiSpend} value={`€${summary.totalSpend.toFixed(2)}`} icon={<DollarSignIcon />} tooltipText={t.tooltipKpiSpend} />
                                {summary.overallROAS > 0.01 ? 
                                    <KpiCard title={t.kpiRoas} value={`${summary.overallROAS.toFixed(2)}x`} icon={<TargetIcon />} tooltipText={t.tooltipKpiRoas} /> : 
                                    <KpiCard title={t.kpiCpp} value={`€${summary.avgCPP.toFixed(2)}`} icon={<TargetIcon />} tooltipText={t.tooltipKpiCpp} /> 
                                }
                                {audiencePerformance.length > 0 && <KpiCard title={t.kpiAudience} value={bestAudience.name} subValue={bestAudience.value} icon={<UsersIcon />} tooltipText={t.tooltipKpiAudience} />}
                                <KpiCard title={t.kpiImpressions} value={summary.totalImpressions.toLocaleString()} icon={<EyeIcon />} tooltipText={t.tooltipKpiImpressions} />
                                <KpiCard title={t.kpiClicks} value={summary.totalClicks.toLocaleString()} icon={<PointerIcon />} tooltipText={t.tooltipKpiClicks} />
                            </div>
                        </div>

                        <div>
                            <CampaignTable campaigns={campaigns} translations={t} />
                             {/* Hidden table for PDF export */}
                            <div className="hidden">
                                <table id="campaign-table-for-export">
                                    <thead>
                                        <tr>
                                            <th>Campaign</th><th>Spend (€)</th><th>Impressions</th><th>Clicks</th><th>CTR (%)</th><th>CPC (€)</th><th>Purchases</th><th>ROAS</th><th>CPP (€)</th>
                                        </tr>
                                    </thead>
                                    <tbody>
                                        {campaigns.map(c => (
                                            <tr key={c.name}><td>{c.name}</td><td>{c.spend.toFixed(2)}</td><td>{c.impressions.toLocaleString()}</td><td>{c.clicks.toLocaleString()}</td><td>{c.ctr.toFixed(2)}</td><td>{c.cpc.toFixed(2)}</td><td>{c.purchases.toLocaleString()}</td><td>{c.roas.toFixed(2)}</td><td>{c.cpp.toFixed(2)}</td></tr>
                                        ))}
                                    </tbody>
                                </table>
                            </div>
                        </div>

                        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
                           <div id="treemap-container" className="lg:col-span-2">
                               <SpendTreemap data={campaigns} translations={t} />
                           </div>
                           <div id="audience-chart-container" className="bg-gray-800 p-6 rounded-lg shadow-xl">
                                <h3 className="text-xl font-semibold mb-4 text-white">{t.chartAudienceTitle}</h3>
                                 <ResponsiveContainer width="100%" height={400}>
                                     <BarChart data={audiencePerformance} layout="vertical" margin={{ top: 5, right: 30, left: 30, bottom: 5 }}>
                                        <CartesianGrid strokeDasharray="3 3" stroke="#4A5568" />
                                        <XAxis type="number" stroke="#A0AEC0" />
                                        <YAxis type="category" dataKey="audience" stroke="#A0AEC0" width={150} tick={{ fontSize: 12 }} />
                                        <Tooltip contentStyle={{ backgroundColor: '#1A202C', border: '1px solid #4A5568' }} formatter={(value: number) => value.toFixed(2)} />
                                        <Legend />
                                         {summary.overallROAS > 0.01 ? <Bar dataKey="roas" fill="#63B3ED" name={t.roasLabel} /> : <Bar dataKey="cpp" fill="#4FD1C5" name={`${t.cppLabel} (€)`} />}
                                    </BarChart>
                                </ResponsiveContainer>
                            </div>
                        </div>

                        {recommendations && (
                            <div className="bg-gray-800 rounded-lg shadow-2xl p-6">
                                <div className="flex justify-between items-center border-b-2 border-gray-700 pb-2 mb-4">
                                    <h2 className="text-3xl font-bold text-blue-300">{t.recommendationsTitle}</h2>
                                    <div className="flex items-center space-x-3">
                                        <button onClick={handleGenerateAndSendReport} disabled={isExporting} className="px-6 py-2 bg-teal-600 hover:bg-teal-700 disabled:bg-teal-800 disabled:cursor-wait rounded-md font-semibold transition-colors flex items-center space-x-2">
                                            <SendIcon />
                                            <span>{isExporting ? t.generatingReportButton : t.generateAndSendButton}</span>
                                        </button>
                                    </div>
                                </div>
                                <div id="recommendations-container" className="prose prose-invert max-w-none text-gray-300">{formattedRecommendations}</div>
                            </div>
                        )}
                    </div>
                )}
            </main>
        </div>
    );
};

export default App;

import { GoogleGenAI, GenerateContentResponse } from "@google/genai";
import { Campaign, AnalysisSummary } from '../types';

const getAiClient = (isThinkingMode: boolean) => {
    if (!process.env.API_KEY) {
        throw new Error("API_KEY environment variable not set");
    }
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const modelName = isThinkingMode ? 'gemini-3-pro-preview' : 'gemini-3-flash-preview';
    const config = isThinkingMode ? { thinkingConfig: { thinkingBudget: 32768 } } : {};
    return { ai, modelName, config };
};

const getLanguageName = (language: 'en' | 'fr' | 'ar'): string => {
    const languageMap = { en: 'English', fr: 'French', ar: 'Arabic' };
    return languageMap[language];
};

export const getRecommendations = async (campaigns: Campaign[], summary: AnalysisSummary, language: 'en' | 'fr' | 'ar', isThinkingMode: boolean): Promise<string> => {
    const { ai, modelName, config } = getAiClient(isThinkingMode);
    const languageName = getLanguageName(language);
    const hasAudienceData = campaigns.some(c => c.audience && c.audience !== 'N/A' && c.audience !== 'Multiple');
    const hasRoasData = summary.overallROAS > 0.01;

    const roasAnalysisBlock = `
**THE BOTTOM LINE:**
Start with a no-BS summary of the account's health. Is it making money or burning cash? What's the overall ROAS? Be direct.

**KILL OR SCALE: Campaign Breakdown**
*   **SCALE IT 🚀:** Identify the top 1-2 campaigns that are printing money (highest ROAS). Explain exactly WHY they are winning and give an aggressive scaling plan (e.g., "Crank up the budget by 30% now.").
*   **KILL IT 🔪:** Identify the 1-2 worst-performing campaigns that are bleeding money. Be ruthless. Tell the user to pause them immediately and explain why they're failing (e.g., "This campaign has a 1.5x ROAS. You're losing money. Shut it down yesterday.").
    `;

    const cppAnalysisBlock = `
**THE BOTTOM LINE (ROAS DATA UNAVAILABLE):**
ROAS data is missing, so I'm switching to a Cost-Per-Purchase (CPP) analysis. The game is about acquiring customers as cheaply as possible. Your average CPP is **${summary.avgCPP.toFixed(2)}**. Let's see who's efficient and who's just burning cash.

**KILL OR SCALE: Campaign Breakdown**
*   **SCALE IT 🚀:** Identify the top 1-2 campaigns with the **LOWEST CPP**. These are your most efficient customer acquisition machines. Explain why they're working (likely a winning combo of creative and audience) and how to scale them.
*   **KILL IT 🔪:** Identify the 1-2 campaigns with the **HIGHEST CPP** or those spending significant money with zero purchases. These are budget vampires. Tell the user to kill them immediately.
    `;

    const deepDiveBlock = `
**STRATEGIC OVERVIEW & UNTAPPED OPPORTUNITIES:**
Go beyond the immediate data. Based on the patterns you see (winning audiences, successful campaign types), what is the overarching strategic direction this ad account should take over the next quarter?
*   **Market Expansion:** Are there signs that they should expand to new demographics or geographic locations?
*   **Funnel Analysis:** Is the strategy too focused on bottom-of-funnel (retargeting)? Suggest specific top-of-funnel or middle-of-funnel campaigns they should test.
*   **Creative Angle:** What is the likely 'big idea' behind the creatives that are working? How can they double down on this theme in future ads?
*   **Hidden Gem:** Identify one non-obvious but potentially high-impact opportunity based on a subtle pattern in the data.
    `;

    const prompt = `
        You are 'THE WOLF OF ADS', the world's greatest media buyer, known for turning ad spend into massive profits. Your advice is direct, brutally honest, and hyper-focused on scaling what works and killing what doesn't. You don't waste time on vanity metrics. You care about efficiency and profit.

        Analyze the following Meta Ads campaign data like a top-tier performance marketer. The currency is likely EUR based on the export.

        **Overall Summary:**
        ${JSON.stringify(summary, (key, value) => typeof value === 'number' ? value.toFixed(2) : value, 2)}

        **Performance by Campaign:**
        ${JSON.stringify(campaigns, (key, value) => typeof value === 'number' ? value.toFixed(2) : value, 2)}

        Provide your analysis in aggressive, actionable Markdown format. Use this structure:

        ${hasRoasData ? roasAnalysisBlock : cppAnalysisBlock}

        ${hasAudienceData ? `
        **GOLDMINE AUDIENCES:**
        This is where the real money is made.
        *   **Winning Audiences:** Pinpoint the exact audiences with the highest ROAS (or lowest CPP if ROAS is unavailable). Tell the user to double down on these.
        *   **Loser Audiences:** Pinpoint the audiences that are a waste of money. Tell the user to stop targeting them.
        *   **Alpha Insight:** Provide a key insight about their audiences. Are retargeting audiences carrying all the weight? Is a specific prospecting audience showing potential?
        ` : ''}

        ${isThinkingMode ? deepDiveBlock : ''}

        **IMMEDIATE ACTION PLAN (Your Roadmap to Profit):**
        Give a numbered list of 3-5 high-impact, immediate actions. This is a direct order list.
        1.  **Budget Reallocation:** Be specific. "ACTION: Pause [Campaign X] immediately. Reallocate its entire daily budget to [Campaign Y] and [Campaign Z], splitting it 50/50."
        2.  **Audience & Targeting:** Be precise. "ACTION: The '[Audience Name]' is your goldmine. Create a new ad set targeting a 1% Lookalike Audience in your primary market based on these converters. Exclude recent purchasers."
        3.  **Creative Testing:** Give a clear testing instruction. "ACTION: The creative in your winning campaigns is working. Duplicate the ads from [Campaign Y] into a new ad set targeting your best Lookalike audience. Don't change a thing."
        4.  **Kill a Loser:** Reiterate the need to cut losses. "ACTION: I already told you to kill [Campaign X]. If you haven't done it yet, do it now. Stop wasting money."

        Your tone must be confident, expert, and laser-focused on maximizing profit. No fluff. Just actionable, money-making advice.

        IMPORTANT: Your entire response, including all titles and content, MUST be in ${languageName}.
    `;

    try {
        const response: GenerateContentResponse = await ai.models.generateContent({
            model: modelName,
            contents: prompt,
            config: config
        });
        return response.text;
    } catch (error) {
        console.error("Error calling Gemini API:", error);
        throw new Error("Failed to get recommendations from AI. Please check the API key and try again.");
    }
};

export const getCompetitorAnalysis = async (competitorUrls: string[], summary: AnalysisSummary, language: 'en' | 'fr' | 'ar'): Promise<string> => {
    // Competitor analysis should be quick but insightful, so we use the flash model with search.
    const { ai, modelName } = getAiClient(false); 
    const languageName = getLanguageName(language);

    const prompt = `
        You are a world-class marketing strategist and competitive intelligence expert. Your client wants a strategic battle plan to differentiate from their competition.

        **Client's Ad Performance Summary:**
        ${JSON.stringify(summary, (key, value) => typeof value === 'number' ? value.toFixed(2) : value, 2)}

        **Competitor Websites to Analyze:**
        ${competitorUrls.join('\n')}

        **Your Mission:**
        1.  **Analyze Competitors:** Use your Google Search tool to research each competitor URL. For each one, deduce their:
            *   **Target Audience:** Who are they trying to reach? (e.g., Luxury consumers, bargain hunters, tech enthusiasts).
            *   **Unique Selling Proposition (USP):** What is their core marketing message? What makes them different?
            *   **Likely Marketing Angle:** How do they position their products? (e.g., Focus on features, benefits, community, status).

        2.  **Synthesize & Strategize:** Based on your competitor research and the client's performance summary, provide a concise strategic analysis.

        3.  **Create a Differentiation Battle Plan:** This is the most important part. Give a numbered list of 3-4 actionable, creative strategies the client can use in their next Meta Ads to stand out and win market share. Be specific.

        **Example Strategies:**
        *   "Attack a Niche: Your competitors are all targeting a broad market. Launch a new campaign focused exclusively on [Specific Niche] with ad copy that speaks their language."
        *   "Counter-Position on Value: Competitor X is a premium brand. Test a campaign angle that highlights your product as 'the affordable alternative without compromising quality'."
        *   "Highlight a Unique Benefit: None of your competitors are talking about [Specific Feature/Benefit of Client's Product]. Make this the hero of your next creative."

        Format the entire response in clean, professional Markdown. The response MUST be in ${languageName}.
    `;

    try {
        const response: GenerateContentResponse = await ai.models.generateContent({
            model: 'gemini-3-flash-preview', // Use flash for speed with search
            contents: prompt,
            config: {
                tools: [{googleSearch: {}}],
            }
        });
        return response.text;
    } catch (error) {
        console.error("Error calling Gemini API for competitor analysis:", error);
        throw new Error("Failed to get competitor analysis from AI. Please check the API key and try again.");
    }
};

