        if (!summary || !recommendations) return;
        setIsExporting(true);
        setError('');

        try {
            const doc = new jsPDF('p', 'mm', 'a4');
            const pdfWidth = doc.internal.pageSize.getWidth();
            const margin = 15;
            let yPos = margin;

            doc.setTextColor('#e2e8f0');
            doc.setFont('helvetica', 'bold');
            doc.setFontSize(20);
            doc.text(t.title, pdfWidth / 2, yPos, { align: 'center' });
