                const kpisCanvas = await html2canvas(kpisEl, { backgroundColor: '#1f2937', scale: 2 });
                const kpisImgData = kpisCanvas.toDataURL('image/png');
                const kpisImgHeight = (kpisCanvas.height * (pdfWidth - margin * 2)) / kpisCanvas.width;
                doc.addImage(kpisImgData, 'PNG', margin, yPos, pdfWidth - margin * 2, kpisImgHeight);
                yPos += kpisImgHeight + 10;
            }

            doc.setFont('helvetica', 'bold');
            doc.setFontSize(14);
            doc.text(t.chartCampaignTitle, margin, yPos);
            yPos += 8;
            autoTable(doc, {
                startY: yPos,
                html: '#campaign-table-for-export',
                theme: 'grid',
                headStyles: { fillColor: [41, 51, 65] },
                styles: { textColor: [226, 232, 240], cellPadding: 2, fontSize: 8 },
                didDrawPage: (data: any) => { yPos = data.cursor.y; }
            });
            yPos = (doc as any).lastAutoTable.finalY + 10;

            if (doc.internal.pageSize.getHeight() - yPos < 100) { doc.addPage(); yPos = margin; }

            const treemapEl = document.getElementById('treemap-container');
            const audienceEl = document.getElementById('audience-chart-container');

            if (treemapEl && audienceEl) {
                const treemapCanvas = await html2canvas(treemapEl, { backgroundColor: '#1f2937', scale: 2 });
                const audienceCanvas = await html2canvas(audienceEl, { backgroundColor: '#1f2937', scale: 2 });
                const treemapImgData = treemapCanvas.toDataURL('image/png');
                const audienceImgData = audienceCanvas.toDataURL('image/png');
                const vizWidth = (pdfWidth - margin * 3) / 2;
                const treemapImgHeight = (treemapCanvas.height * vizWidth) / treemapCanvas.width;
                const audienceImgHeight = (audienceCanvas.height * vizWidth) / audienceCanvas.width;
                doc.addImage(treemapImgData, 'PNG', margin, yPos, vizWidth, treemapImgHeight);
                doc.addImage(audienceImgData, 'PNG', margin + vizWidth + 5, yPos, vizWidth, audienceImgHeight);
                yPos += Math.max(treemapImgHeight, audienceImgHeight) + 10;
            }

            if (recommendations) {
                const recommendationsEl = document.getElementById('recommendations-container');
                if(recommendationsEl){
                    const recCanvas = await html2canvas(recommendationsEl, { backgroundColor: '#1f2937', scale: 2 });
                    const recImgData = recCanvas.toDataURL('image/png');
                    const recImgHeight = (recCanvas.height * (pdfWidth - margin * 2)) / recCanvas.width;
                    if (doc.internal.pageSize.getHeight() - yPos < recImgHeight) { doc.addPage(); yPos = margin; }
                    doc.addImage(recImgData, 'PNG', margin, yPos, pdfWidth - margin * 2, recImgHeight);
                }
            }

            doc.save('meta-ads-report.pdf');

            const emailBody = generateEmailHtml(recommendations, summary, t.emailAttachmentNote);
            const subject = "Meta Ads Performance Analysis Report";
            window.location.href = `mailto:?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(emailBody)}`;

        } catch (err: any) {
            console.error("Report generation failed:", err);
            setError(`PDF export failed. Please try again. Error: ${err.message}`);
        } finally {
            setIsExporting(false);
        }
    };

    const handleCompetitorAnalysis = useCallback(async () => {
        if (!competitorUrls.trim() || !summary) return;
        setIsAnalyzingCompetitors(true);
