                                           {isAnalyzingCompetitors ? (
                                                <><svg className="animate-spin -ml-1 mr-3 h-5 w-5 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg>
                                                <span>{t.analyzingCompetitorsButton}</span></>
                                           ) : (
                                               <span>{t.analyzeCompetitorsButton}</span>
                                           )}
                                        </button>
                                    </div>
                                    <div className="min-h-[200px]">
                                        {competitorAnalysis && (
                                            <div className="bg-gray-900/50 p-4 rounded-lg">
                                                <h3 className="text-xl font-bold text-indigo-300 mb-2">{t.competitorInsightsTitle}</h3>
                                                <div className="prose prose-invert max-w-none text-gray-300">{formattedCompetitorAnalysis}</div>
                                            </div>
                                        )}
                                    </div>
                                </div>
                            </div>
                        )}
                    </div>
                )}
            </main>
        </div>
    );
};

export default App;

