export const parseAndProcessData = (csvData: string): { campaigns: Campaign[], summary: AnalysisSummary } => {
    if (csvData.charCodeAt(0) === 0xFEFF) {
        csvData = csvData.substring(1);
    }

    const lines = csvData.trim().split('\n');
    if (lines.length < 2) {
        throw new Error('CSV data must have at least one header row and one data row.');
    }

    const headerLine = lines[0].trim();
    const delimiter = ',';

    const rawHeaders = headerLine.split(delimiter).map(h => h.trim().toLowerCase().replace(/^"|"$/g, ''));
    const dataRows = lines.slice(1);

    const headerMap = {
        name: getHeaderIndex(rawHeaders, ['campaign name', 'campaign', 'nom de la campagne']),
        spend: getHeaderIndex(rawHeaders, ['amount spent (usd)', 'spend', 'amount spent', 'budget dépensé', 'montant dépensé (usd)', 'montant dépensé (eur)']),
        impressions: getHeaderIndex(rawHeaders, ['impressions']),
        clicks: getHeaderIndex(rawHeaders, ['clicks', 'link clicks', 'clicks (all)', 'clics', 'clics sur un lien']),
        purchases: getHeaderIndex(rawHeaders, ['purchases', 'conversions', 'achats']),
        results: getHeaderIndex(rawHeaders, ['résultats', 'results']),
        resultType: getHeaderIndex(rawHeaders, ['type de résultat', 'result type']),
        roas: getHeaderIndex(rawHeaders, ['purchase roas (return on ad spend)', 'roas', 'roas (purchase)', 'roas (achats)', 'roas sur les achats (retour sur les dépenses publicitaires)']),
        audience: getHeaderIndex(rawHeaders, ['audience', 'audience name', "nom de l'audience", 'nom de l’ensemble de publicités']),
    };

    const requiredCoreHeaders: (keyof typeof headerMap)[] = ['name', 'spend', 'impressions', 'clicks'];
    for (const key of requiredCoreHeaders) {
        if (headerMap[key] === -1) {
            throw new Error(`Missing required CSV column: ${key}. Please check your data. Found headers: [${rawHeaders.join(', ')}]`);
        }
    }

    if (headerMap.purchases === -1 && (headerMap.results === -1 || headerMap.resultType === -1)) {
        console.warn('Could not find explicit purchase data. ROAS/CPP might be inaccurate.');
    }

    const valueSplitRegex = new RegExp(`${delimiter}(?=(?:(?:[^"]*"){2})*[^"]*$)`);

    const campaignMap = new Map<string, Omit<Campaign, 'ctr' | 'cpc' | 'cpm' | 'cpp' | 'roas'>>();

    dataRows.forEach(row => {
        if (!row.trim() || row.startsWith(delimiter.repeat(5))) return;

        const values = row.split(valueSplitRegex).map(v => v.trim().replace(/^"|"$/g, ''));
        const name = values[headerMap.name]?.trim() || 'N/A';
        if (name === 'N/A' || name === '') return;

        let purchases = 0;
        if (headerMap.purchases > -1) {
            purchases = parseInt(values[headerMap.purchases], 10) || 0;
        } else if (headerMap.results > -1 && headerMap.resultType > -1) {
            const resultType = values[headerMap.resultType]?.toLowerCase() || '';
            if (resultType.includes('purchase') || resultType.includes('achat')) {
                purchases = parseInt(values[headerMap.results], 10) || 0;
            }
        }

        const roasValue = headerMap.roas > -1 ? parseFloat(values[headerMap.roas]?.replace(',', '.')) || 0 : 0;
        const spend = parseFloat(values[headerMap.spend]?.replace(',', '.')) || 0;

        const campaignData = campaignMap.get(name) || {
            name,
            spend: 0,
            impressions: 0,
            clicks: 0,
            purchases: 0,
            revenue: 0,
            audience: 'Multiple'
        };

        campaignData.spend += spend;
        campaignData.impressions += parseInt(values[headerMap.impressions], 10) || 0;
        campaignData.clicks += parseInt(values[headerMap.clicks], 10) || 0;
        campaignData.purchases += purchases;

        // Revenue is calculated from ROAS if available, otherwise it's 0.
        (campaignData as any).revenue = ((campaignData as any).revenue || 0) + (spend * roasValue);

        if (headerMap.audience > -1 && values[headerMap.audience]?.trim()) {
            const currentAudience = values[headerMap.audience]?.trim();
            if (campaignData.audience === 'Multiple') {
                 campaignData.audience = currentAudience;
            } else if (campaignData.audience !== currentAudience) {
                // If we've already set an audience and find a new one, it's multiple.
                campaignData.audience = 'Multiple';
            }
        }

        campaignMap.set(name, campaignData);
    });

    const campaigns: Campaign[] = Array.from(campaignMap.values()).map(c => {
        const revenue = (c as any).revenue;
        return {
            ...c,
            ctr: c.impressions > 0 ? (c.clicks / c.impressions) * 100 : 0,
            cpc: c.clicks > 0 ? c.spend / c.clicks : 0,
            cpm: c.impressions > 0 ? (c.spend / c.impressions) * 1000 : 0,
            cpp: c.purchases > 0 ? c.spend / c.purchases : 0,
            roas: c.spend > 0 ? revenue / c.spend : 0,
        };
    });

    // Fix: Removed incorrect 'AnalysisSummary' type from 'summary' which is an intermediate calculation object.
    const summary = campaigns.reduce((acc, c) => ({
        totalSpend: acc.totalSpend + c.spend,
        totalImpressions: acc.totalImpressions + c.impressions,
        totalClicks: acc.totalClicks + c.clicks,
        totalPurchases: acc.totalPurchases + c.purchases,
        totalRevenue: acc.totalRevenue + (c.spend * c.roas),
    }), { totalSpend: 0, totalImpressions: 0, totalClicks: 0, totalPurchases: 0, totalRevenue: 0 });

    const finalSummary: AnalysisSummary = {
        totalSpend: summary.totalSpend,
        totalImpressions: summary.totalImpressions,
        totalClicks: summary.totalClicks,
        totalPurchases: summary.totalPurchases,
        // Fix: Removed 'as any' cast as the type of 'summary' is now correctly inferred.
        overallROAS: summary.totalSpend > 0 ? summary.totalRevenue / summary.totalSpend : 0,
        avgCTR: summary.totalImpressions > 0 ? (summary.totalClicks / summary.totalImpressions) * 100 : 0,
        avgCPC: summary.totalClicks > 0 ? summary.totalSpend / summary.totalClicks : 0,
        avgCPM: summary.totalImpressions > 0 ? (summary.totalSpend / summary.totalImpressions) * 1000 : 0,
        avgCPP: summary.totalPurchases > 0 ? summary.totalSpend / summary.totalPurchases : 0,
    };

    const campaignsWithAnomalies = detectAnomalies(campaigns);

    return { campaigns: campaignsWithAnomalies, summary: finalSummary };
};

