const getCampaignGoal = (name: string): string => {
    const lowerName = name.toLowerCase();
    // More specific keywords first
    if (lowerName.match(/conv|conversion|purchase|achat|sales|vente|acq|acquisition/)) {
        return 'Conversion';
    }
    if (lowerName.match(/cons|consideration|traffic|trafic|engagement|lead|prospect|add to cart|ajout panier/)) {
        return 'Consideration';
    }
    if (lowerName.match(/awa|awareness|reach|portée|notoriété|brand/)) {
        return 'Awareness';
    }
    return 'Uncategorized';
};


