        ${isThinkingMode ? deepDiveBlock : ''}

        **IMMEDIATE ACTION PLAN (Your Roadmap to Profit):**
        Give a numbered list of 3-5 high-impact, immediate actions. This is a direct order list. Address any detected anomalies in your plan.
        1.  **Budget Reallocation:** Be specific. "ACTION: Pause [Campaign X] immediately. Reallocate its entire daily budget to [Campaign Y] and [Campaign Z], splitting it 50/50."
        2.  **Audience & Targeting:** Be precise. "ACTION: The '[Audience Name]' is your goldmine. Create a new ad set targeting a 1% Lookalike Audience in your primary market based on these converters. Exclude recent purchasers."
        3.  **Creative Testing:** Give a clear testing instruction. "ACTION: The creative in your winning campaigns is working. Duplicate the ads from [Campaign Y] into a new ad set targeting your best Lookalike audience. Don't change a thing."
        4.  **Kill a Loser:** Reiterate the need to cut losses. "ACTION: I already told you to kill [Campaign X]. If you haven't done it yet, do it now. Stop wasting money."

        Your tone must be confident, expert, and laser-focused on maximizing profit. No fluff. Just actionable, money-making advice.

        IMPORTANT: Your entire response, including all titles and content, MUST be in ${languageName}.
    `;

    try {
        const response: GenerateContentResponse = await ai.models.generateContent({
            model: modelName,
            contents: prompt,
            config: config
        });
        return response.text;
    } catch (error) {
        console.error("Error calling Gemini API:", error);
        throw new Error("Failed to get recommendations from AI. Please check the API key and try again.");
    }
};

export const getCompetitorAnalysis = async (competitorUrls: string[], summary: AnalysisSummary, language: 'en' | 'fr' | 'ar'): Promise<string> => {
    // Competitor analysis should be quick but insightful, so we use the flash model with search.
    const { ai } = getAiClient(false); 
    const languageName = getLanguageName(language);

    const prompt = `
        You are a world-class marketing strategist and competitive intelligence expert. Your client wants a strategic battle plan to differentiate from their competition.

        **Client's Ad Performance Summary:**
        ${JSON.stringify(summary, (key, value) => typeof value === 'number' ? value.toFixed(2) : value, 2)}

        **Competitor Websites to Analyze:**
        ${competitorUrls.join('\n')}

        **Your Mission:**
        1.  **Analyze Competitors:** Use your Google Search tool to research each competitor URL. For each one, deduce their:
            *   **Target Audience:** Who are they trying to reach? (e.g., Luxury consumers, bargain hunters, tech enthusiasts).
            *   **Unique Selling Proposition (USP):** What is their core marketing message? What makes them different?
            *   **Likely Marketing Angle:** How do they position their products? (e.g., Focus on features, benefits, community, status).

        2.  **Synthesize & Strategize:** Based on your competitor research and the client's performance summary, provide a concise strategic analysis.

        3.  **Create a Differentiation Battle Plan:** This is the most important part. Give a numbered list of 3-4 actionable, creative strategies the client can use in their next Meta Ads to stand out and win market share. Be specific.

        **Example Strategies:**
        *   "Attack a Niche: Your competitors are all targeting a broad market. Launch a new campaign focused exclusively on [Specific Niche] with ad copy that speaks their language."
        *   "Counter-Position on Value: Competitor X is a premium brand. Test a campaign angle that highlights your product as 'the affordable alternative without compromising quality'."
        *   "Highlight a Unique Benefit: None of your competitors are talking about [Specific Feature/Benefit of Client's Product]. Make this the hero of your next creative."

        Format the entire response in clean, professional Markdown. The response MUST be in ${languageName}.
    `;

    try {
        const response: GenerateContentResponse = await ai.models.generateContent({
            model: 'gemini-3-flash-preview', // Use flash for speed with search
            contents: prompt,
            config: {
                tools: [{googleSearch: {}}],
            }
        });
        return response.text;
    } catch (error) {
        console.error("Error calling Gemini API for competitor analysis:", error);
        throw new Error("Failed to get competitor analysis from AI. Please check the API key and try again.");
    }
};

import React, { useState, useCallback, useMemo } from 'react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer } from 'recharts';
import { KpiCard } from './components/KpiCard';
import { Campaign, AnalysisSummary, DailyDataPoint, CreativeAnglePerformance, ProcessedData } from './types';
import { parseAndProcessData } from './utils/dataProcessor';
import { getRecommendations, getCompetitorAnalysis } from './services/geminiService';
import { DollarSignIcon, TargetIcon, EyeIcon, PointerIcon, UsersIcon, UploadIcon, SendIcon, NetworkIntelligenceIcon, AlertTriangleIcon } from './components/icons';
import { generateEmailHtml } from './utils/emailGenerator';
import { translations } from './i18n/translations';
import { CampaignTable } from './components/CampaignTable';
import { SpendTreemap } from './components/SpendTreemap';
import { GoalPerformanceTable } from './components/GoalPerformanceTable';
import { TrendChart } from './components/TrendChart';
import { CreativeAngleTable } from './components/CreativeAngleTable';
import { jsPDF } from 'jspdf';
import html2canvas from 'html2canvas';
import autoTable from 'jspdf-autotable';

type Language = 'en' | 'fr' | 'ar';

const App: React.FC = () => {
    const [csvData, setCsvData] = useState<string>('');
    const [fileName, setFileName] = useState<string>('');
    const [processedData, setProcessedData] = useState<ProcessedData | null>(null);
    const [recommendations, setRecommendations] = useState<string>('');
    const [isLoading, setIsLoading] = useState<boolean>(false);
    const [error, setError] = useState<string>('');
    const [language, setLanguage] = useState<Language>('fr');
    const [isThinkingMode, setIsThinkingMode] = useState<boolean>(false);
    const [isExporting, setIsExporting] = useState<boolean>(false);
    const [competitorUrls, setCompetitorUrls] = useState<string>('');
    const [competitorAnalysis, setCompetitorAnalysis] = useState<string>('');
    const [isAnalyzingCompetitors, setIsAnalyzingCompetitors] = useState<boolean>(false);

    const t = useMemo(() => translations[language], [language]);

    const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
        const file = event.target.files?.[0];
        if (file) {
            setFileName(file.name);
            const reader = new FileReader();
            reader.onload = (e) => {
                const text = e.target?.result;
                if (typeof text === 'string') {
                    setCsvData(text);
                    setError('');
                } else {
                    setError(t.errorFileRead);
                }
            };
            reader.onerror = () => {
                setError(t.errorFileRead2);
            };
            reader.readAsText(file);
        }
    };

    const handleAnalyze = useCallback(async () => {
        if (!csvData.trim()) {
            setError(t.errorNoData);
            return;
        }
        setIsLoading(true);
        setError('');
        setRecommendations('');
        setProcessedData(null);
        setCompetitorAnalysis('');
        setCompetitorUrls('');

        try {
            const data = parseAndProcessData(csvData);
            setProcessedData(data);

            const aiRecommendations = await getRecommendations(data.campaigns, data.summary, language, isThinkingMode);
            setRecommendations(aiRecommendations);

        } catch (e: any) {
            setError(`${t.errorAnalysisFailed} ${e.message}`);
            console.error(e);
        } finally {
            setIsLoading(false);
        }
    }, [csvData, language, t, isThinkingMode]);

    const exampleCSV = `
"Day","Campaign Name","Ad Set Name","Ad Name","Impressions","Link Clicks","Amount Spent (EUR)","Purchase ROAS (return on ad spend)","Purchases"
2025-12-19,"CONV - ProLaunch Max","Lookalike Audience 1% - FR","VIDEO_UGC_BestFeature",8000,320,50.00,4.5,5
2025-12-19,"CONV - ProLaunch Max","Retargeting 7d","IMAGE_Testimonial_1",5000,250,35.00,6.2,7
2025-12-19,"AWA - Winter Sale","Broad Audience - All","VIDEO_BrandStory",25000,250,40.00,0,0
2025-12-19,"CONS - Ebook Download","Interest: Marketing","CAROUSEL_Benefits",12000,480,30.00,0,1
2025-12-20,"CONV - ProLaunch Max","Lookalike Audience 1% - FR","VIDEO_UGC_BestFeature",8200,330,52.00,4.8,6
2025-12-20,"CONV - ProLaunch Max","Retargeting 7d","IMAGE_Testimonial_1",5100,260,36.00,6.5,8
2025-12-20,"AWA - Winter Sale","Broad Audience - All","VIDEO_BrandStory",26000,270,42.00,0,0
2025-12-20,"CONS - Ebook Download","Interest: Marketing","CAROUSEL_Benefits",12500,500,32.00,1.2,1
2025-12-21,"CONV - ProLaunch Max","Lookalike Audience 1% - FR","VIDEO_UGC_BestFeature",7900,310,48.00,4.2,4
2025-12-21,"CONV - ProLaunch Max","Retargeting 7d","IMAGE_Testimonial_1",5500,280,38.00,6.0,7
2025-12-21,"AWA - Winter Sale","Broad Audience - All","VIDEO_BrandStory",24000,240,39.00,0.5,0
2025-12-21,"CONS - Ebook Download","Interest: Marketing","CAROUSEL_Benefits",13000,510,33.00,0,0
2025-12-21,"CONV - Legacy Product","Interest: Old Customers","IMAGE_Static_Ad",4000,50,25.00,0.8,1
`;

    const handleUseExample = () => {
        setCsvData(exampleCSV);
        setFileName('export_meta_ads_daily_fr.csv');
        setError('');
    };

    const audiencePerformance = useMemo(() => {
        if (!processedData) return [];
        const audienceMap = new Map<string, { totalSpend: number; totalPurchases: number; totalRevenue: number }>();

        // This logic is now simplified as we don't need to re-parse
        const tempCampaignMap = new Map<string, { spend: number, purchases: number, revenue: number }>();
        processedData.campaigns.forEach(campaign => {
            // This is a simplification; a more accurate way would be to re-process the raw data by audience
            const stats = tempCampaignMap.get(campaign.audience) || { spend: 0, purchases: 0, revenue: 0 };
            stats.spend += campaign.spend;
            stats.purchases += campaign.purchases;
            stats.revenue += campaign.spend * campaign.roas;
            tempCampaignMap.set(campaign.audience, stats);
        });

        const performanceData = Array.from(tempCampaignMap.entries()).map(([audience, stats]) => ({
            audience,
            roas: stats.spend > 0 ? stats.revenue / stats.spend : 0,
            cpp: stats.purchases > 0 ? stats.spend / stats.purchases : 0,
            spend: stats.spend
        }));

        if (processedData.summary.overallROAS < 0.01) {
            return performanceData.filter(a => a.cpp > 0).sort((a, b) => a.cpp - b.cpp);
        }
        return performanceData.sort((a, b) => b.roas - a.roas);

    }, [processedData]);

    const bestAudience = useMemo(() => {
        if (audiencePerformance.length === 0 || !processedData) return { name: 'N/A', value: 'N/A' };
        const topAudience = audiencePerformance[0];
        if (processedData.summary.overallROAS < 0.01) {
             return { name: topAudience.audience, value: `€${topAudience.cpp.toFixed(2)} CPP` };
        }
        return { name: topAudience.audience, value: `${topAudience.roas.toFixed(2)}x ROAS` };
    }, [audiencePerformance, processedData]);

    const totalAnomalies = useMemo(() => processedData?.campaigns.reduce((acc, c) => acc + (c.anomalies?.length || 0), 0) || 0, [processedData]);

    const formatMarkdownResponse = (text: string) => {
        if (!text) return null;
        return text.split('\n').map((line, index) => {
            if (line.startsWith('**')) return <h3 key={index} className="text-xl font-bold mt-4 mb-2 text-blue-400">{line.replace(/\*\*/g, '')}</h3>;
            if (line.startsWith('*   **')) return <li key={index} className="ml-6 list-disc" dangerouslySetInnerHTML={{ __html: line.substring(2).replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>') }}></li>;
            if (line.startsWith('* ')) return <li key={index} className="ml-6 list-disc">{line.substring(2)}</li>;
            if (/^\d+\./.test(line)) return <li key={index} className="ml-6 my-1" dangerouslySetInnerHTML={{ __html: line.replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>') }}></li>;
            return <p key={index} className="my-1">{line}</p>;
        });
    };

    const formattedRecommendations = useMemo(() => formatMarkdownResponse(recommendations), [recommendations]);
    const formattedCompetitorAnalysis = useMemo(() => formatMarkdownResponse(competitorAnalysis), [competitorAnalysis]);

    const handleGenerateAndSendReport = async () => {
        if (!processedData || !recommendations) return;
        setIsExporting(true);
        setError('');

        try {
            const doc = new jsPDF('p', 'mm', 'a4');
            const pdfWidth = doc.internal.pageSize.getWidth();
            const margin = 15;
            let yPos = margin;

            doc.setTextColor('#e2e8f0');
            doc.setFont('helvetica', 'bold');
            doc.setFontSize(20);
            doc.text(t.title, pdfWidth / 2, yPos, { align: 'center' });
            yPos += 15;

            const addCanvasToPdf = async (elementId: string, currentY: number) => {
                 const element = document.getElementById(elementId);
                 if (element) {
                    const canvas = await html2canvas(element, { backgroundColor: '#1f2937', scale: 2 });
                    const imgData = canvas.toDataURL('image/png');
                    const imgHeight = (canvas.height * (pdfWidth - margin * 2)) / canvas.width;
                    if (doc.internal.pageSize.getHeight() - currentY < imgHeight) {
                        doc.addPage();
                        currentY = margin;
                    }
                    doc.addImage(imgData, 'PNG', margin, currentY, pdfWidth - margin * 2, imgHeight);
                    return currentY + imgHeight + 10;
                 }
                 return currentY;
            }

            yPos = await addCanvasToPdf('kpi-container', yPos);

            autoTable(doc, {
                startY: yPos,
                html: '#campaign-table-for-export',
                theme: 'grid',
                headStyles: { fillColor: [41, 51, 65] },
                styles: { textColor: [226, 232, 240], cellPadding: 2, fontSize: 8 },
                didDrawPage: (data: any) => { yPos = data.cursor.y; }
            });
            yPos = (doc as any).lastAutoTable.finalY + 10;

            yPos = await addCanvasToPdf('temporal-analysis-container', yPos);
            yPos = await addCanvasToPdf('goal-performance-container', yPos);
            yPos = await addCanvasToPdf('creative-angle-container', yPos);

            const treemapEl = document.getElementById('treemap-container');
            const audienceEl = document.getElementById('audience-chart-container');
            if (treemapEl && audienceEl) {
                if (doc.internal.pageSize.getHeight() - yPos < 100) { doc.addPage(); yPos = margin; }
                const treemapCanvas = await html2canvas(treemapEl, { backgroundColor: '#1f2937', scale: 2 });
                const audienceCanvas = await html2canvas(audienceEl, { backgroundColor: '#1f2937', scale: 2 });
                const vizWidth = (pdfWidth - margin * 3) / 2;
                const treemapImgHeight = (treemapCanvas.height * vizWidth) / treemapCanvas.width;
                const audienceImgHeight = (audienceCanvas.height * vizWidth) / audienceCanvas.width;
                doc.addImage(treemapCanvas.toDataURL('image/png'), 'PNG', margin, yPos, vizWidth, treemapImgHeight);
                doc.addImage(audienceCanvas.toDataURL('image/png'), 'PNG', margin + vizWidth + 5, yPos, vizWidth, audienceImgHeight);
                yPos += Math.max(treemapImgHeight, audienceImgHeight) + 10;
            }

            yPos = await addCanvasToPdf('recommendations-container', yPos);

            doc.save('meta-ads-report.pdf');

            const emailBody = generateEmailHtml(recommendations, processedData.summary, t.emailAttachmentNote);
            window.location.href = `mailto:?subject=${encodeURIComponent("Meta Ads Performance Analysis Report")}&body=${encodeURIComponent(emailBody)}`;

        } catch (err: any) {
            console.error("Report generation failed:", err);
            setError(`PDF export failed. Please try again. Error: ${err.message}`);
        } finally {
            setIsExporting(false);
        }
    };

    const handleCompetitorAnalysis = useCallback(async () => {
        if (!competitorUrls.trim() || !processedData) return;
        setIsAnalyzingCompetitors(true); setCompetitorAnalysis(''); setError('');
        try {
            const urls = competitorUrls.split('\n').filter(url => url.trim() !== '');
            if (urls.length === 0) return;
            const result = await getCompetitorAnalysis(urls, processedData.summary, language);
            setCompetitorAnalysis(result);
        } catch (e: any) {
            setError(`Competitor analysis failed: ${e.message}`);
        } finally {
            setIsAnalyzingCompetitors(false);
        }
    }, [competitorUrls, processedData, language]);

    const { campaigns, summary, dailyData, creativeAngles } = processedData || {};

    return (
        <div className="min-h-screen bg-gray-900 text-gray-100 font-sans" dir={language === 'ar' ? 'rtl' : 'ltr'}>
            <header className="bg-gray-800/50 backdrop-blur-sm shadow-lg p-4 sticky top-0 z-10">
                <div className="container mx-auto flex justify-between items-center">
                    <h1 className="text-xl md:text-2xl font-bold text-white">{t.title}</h1>
                     <div className="flex items-center space-x-2 bg-gray-900 p-1 rounded-lg">
                        {(['fr', 'en', 'ar'] as Language[]).map(lang => (
                            <button key={lang} onClick={() => setLanguage(lang)} className={`px-3 py-1 text-sm font-semibold rounded-md transition-colors ${language === lang ? 'bg-blue-600 text-white' : 'text-gray-300 hover:bg-gray-700'}`}>{lang.toUpperCase()}</button>
                        ))}
                    </div>
                </div>
            </header>

            <main className="container mx-auto p-4 md:p-8">
                <div className="bg-gray-800 rounded-lg shadow-2xl p-6 mb-8">
                    <h2 className="text-2xl font-semibold mb-4 text-blue-300">{t.uploadTitle}</h2>
                    <div className="flex flex-col items-center justify-center w-full mt-4">
                        <label htmlFor="csv-upload" className="flex flex-col items-center justify-center w-full h-48 border-2 border-gray-600 border-dashed rounded-lg cursor-pointer bg-gray-900 hover:bg-gray-700 transition-colors">
                            <div className="flex flex-col items-center justify-center pt-5 pb-6 text-center">
                                <UploadIcon />
                                 {fileName ? ( <p className="font-semibold text-green-400">{fileName}</p> ) : (
                                    <>
                                        <p className="mb-2 text-sm text-gray-400"><span className="font-semibold">{t.uploadClick}</span> {t.uploadDrag}</p>
                                        <p className="text-xs text-gray-500">{t.uploadHint}</p>
                                    </>
                                )}
                            </div>
                            <input id="csv-upload" type="file" className="hidden" accept=".csv, text/csv" onChange={handleFileChange} />
                        </label>
                    </div>

                    <div className="flex flex-col sm:flex-row items-center justify-between mt-6 space-y-4 sm:space-y-0 sm:space-x-4">
                        <button onClick={handleUseExample} className="w-full sm:w-auto px-6 py-2 bg-gray-700 hover:bg-gray-600 rounded-md font-semibold transition-colors">{t.exampleButton}</button>
                        <div className="flex items-center space-x-4 flex-grow justify-end">
                             <div className="group relative flex items-center justify-center">
                                <div onClick={() => setIsThinkingMode(!isThinkingMode)} className="flex items-center space-x-2 cursor-pointer p-2 rounded-lg hover:bg-gray-700">
                                    <NetworkIntelligenceIcon />
                                    <span className="font-semibold text-gray-300">{t.thinkingMode}</span>
                                    <div className={`w-10 h-5 flex items-center rounded-full transition-colors ${isThinkingMode ? 'bg-blue-600' : 'bg-gray-600'}`}><div className={`w-4 h-4 bg-white rounded-full mx-0.5 transform transition-transform ${isThinkingMode ? 'translate-x-5' : ''}`}></div></div>
                                </div>
                                <div className="absolute bottom-full mb-2 w-64 bg-gray-900 text-white text-xs rounded-lg p-2 opacity-0 group-hover:opacity-100 transition-opacity duration-300 pointer-events-none shadow-lg">{t.thinkingModeTooltip}</div>
                            </div>
                            <button onClick={handleAnalyze} disabled={isLoading} className="w-full sm:w-auto px-8 py-3 bg-blue-600 hover:bg-blue-700 disabled:bg-blue-800 disabled:cursor-not-allowed rounded-md font-bold text-lg transition-all transform hover:scale-105 flex items-center justify-center space-x-2">
                                {isLoading ? ( <><svg className="animate-spin -ml-1 mr-3 h-5 w-5 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg>{t.analyzingButton}</> ) : ( t.analyzeButton )}
                            </button>
                        </div>
                    </div>
                    {error && <p className="text-red-400 mt-4 text-center">{error}</p>}
                </div>

                {summary && campaigns && dailyData && creativeAngles && (
                    <div id="analysis-report" className="space-y-8">
                        <div id="kpi-container" className="bg-gray-800 rounded-lg shadow-2xl p-6">
                            <h2 className="text-3xl font-bold mb-6 text-blue-300 border-b-2 border-gray-700 pb-2">{t.dashboardTitle}</h2>
                            <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-6 gap-6">
                                <KpiCard title={t.kpiSpend} value={`€${summary.totalSpend.toFixed(2)}`} icon={<DollarSignIcon />} tooltipText={t.tooltipKpiSpend} />
                                {summary.overallROAS > 0.01 ? 
                                    <KpiCard title={t.kpiRoas} value={`${summary.overallROAS.toFixed(2)}x`} icon={<TargetIcon />} tooltipText={t.tooltipKpiRoas} /> : 
                                    <KpiCard title={t.kpiCpp} value={`€${summary.avgCPP.toFixed(2)}`} icon={<TargetIcon />} tooltipText={t.tooltipKpiCpp} /> 
                                }
                                {audiencePerformance.length > 0 && <KpiCard title={t.kpiAudience} value={bestAudience.name} subValue={bestAudience.value} icon={<UsersIcon />} tooltipText={t.tooltipKpiAudience} />}
                                {totalAnomalies > 0 && <KpiCard title={t.kpiAnomalies} value={totalAnomalies.toString()} icon={<AlertTriangleIcon />} tooltipText={t.tooltipKpiAnomalies} />}
                                <KpiCard title={t.kpiImpressions} value={summary.totalImpressions.toLocaleString()} icon={<EyeIcon />} tooltipText={t.tooltipKpiImpressions} />
                                <KpiCard title={t.kpiClicks} value={summary.totalClicks.toLocaleString()} icon={<PointerIcon />} tooltipText={t.tooltipKpiClicks} />
                            </div>
                        </div>

                        <CampaignTable campaigns={campaigns} translations={t} />

                        <div id="temporal-analysis-container"><TrendChart data={dailyData} translations={t} /></div>

                        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                           <div id="goal-performance-container"><GoalPerformanceTable campaigns={campaigns} translations={t} /></div>
                           <div id="creative-angle-container"><CreativeAngleTable creativeAngles={creativeAngles} translations={t} /></div>
                        </div>

                        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
                           <div id="treemap-container" className="lg:col-span-2"><SpendTreemap data={campaigns} translations={t} /></div>
                           <div id="audience-chart-container" className="bg-gray-800 p-6 rounded-lg shadow-xl">
                                <h3 className="text-xl font-semibold mb-4 text-white">{t.chartAudienceTitle}</h3>
                                 <ResponsiveContainer width="100%" height={400}>
                                     <BarChart data={audiencePerformance} layout="vertical" margin={{ top: 5, right: 30, left: 30, bottom: 5 }}>
                                        <CartesianGrid strokeDasharray="3 3" stroke="#4A5568" />
                                        <XAxis type="number" stroke="#A0AEC0" />
                                        <YAxis type="category" dataKey="audience" stroke="#A0AEC0" width={150} tick={{ fontSize: 12 }} />
                                        <Tooltip contentStyle={{ backgroundColor: '#1A202C', border: '1px solid #4A5568' }} formatter={(value: number) => value.toFixed(2)} />
                                        <Legend />
                                         {summary.overallROAS > 0.01 ? <Bar dataKey="roas" fill="#63B3ED" name={t.roasLabel} /> : <Bar dataKey="cpp" fill="#4FD1C5" name={`${t.cppLabel} (€)`} />}
                                    </BarChart>
                                </ResponsiveContainer>
                            </div>
                        </div>

                        {recommendations && (
                            <div className="bg-gray-800 rounded-lg shadow-2xl p-6">
                                <div className="flex justify-between items-center border-b-2 border-gray-700 pb-2 mb-4">
                                    <h2 className="text-3xl font-bold text-blue-300">{t.recommendationsTitle}</h2>
                                    <div className="flex items-center space-x-3">
                                        <button onClick={handleGenerateAndSendReport} disabled={isExporting} className="px-6 py-2 bg-teal-600 hover:bg-teal-700 disabled:bg-teal-800 disabled:cursor-wait rounded-md font-semibold transition-colors flex items-center space-x-2">
                                            <SendIcon />
                                            <span>{isExporting ? t.generatingReportButton : t.generateAndSendButton}</span>
                                        </button>
                                    </div>
                                </div>
                                <div id="recommendations-container" className="prose prose-invert max-w-none text-gray-300">{formattedRecommendations}</div>
                            </div>
                        )}

                        {recommendations && (
                             <div className="bg-gray-800 rounded-lg shadow-2xl p-6">
                                <h2 className="text-3xl font-bold text-blue-300 border-b-2 border-gray-700 pb-2 mb-4">{t.competitorAnalysisTitle}</h2>
                                <div className="grid grid-cols-1 md:grid-cols-2 gap-6 items-start">
                                    <div>
                                        <label htmlFor="competitor-urls" className="block text-sm font-medium text-gray-300 mb-2">{t.competitorInputLabel}</label>
                                        <textarea id="competitor-urls" rows={4} value={competitorUrls} onChange={(e) => setCompetitorUrls(e.target.value)} placeholder="https://www.competitor1.com&#10;https://www.competitor2.com" className="w-full p-2 bg-gray-900 border border-gray-600 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500" />
                                        <p className="text-xs text-gray-500 mt-2">{t.competitorAnalysisHint}</p>
                                        <button onClick={handleCompetitorAnalysis} disabled={isAnalyzingCompetitors || !competitorUrls.trim()} className="mt-4 w-full px-6 py-2 bg-indigo-600 hover:bg-indigo-700 disabled:bg-indigo-800 disabled:cursor-not-allowed rounded-md font-semibold transition-colors flex items-center justify-center space-x-2">
                                           {isAnalyzingCompetitors ? ( <><svg className="animate-spin -ml-1 mr-3 h-5 w-5 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg><span>{t.analyzingCompetitorsButton}</span></> ) : ( <span>{t.analyzeCompetitorsButton}</span> )}
                                        </button>
                                    </div>
                                    <div className="min-h-[200px]">
                                        {competitorAnalysis && ( <div className="bg-gray-900/50 p-4 rounded-lg"> <h3 className="text-xl font-bold text-indigo-300 mb-2">{t.competitorInsightsTitle}</h3> <div className="prose prose-invert max-w-none text-gray-300">{formattedCompetitorAnalysis}</div> </div> )}
                                    </div>
                                </div>
                            </div>
                        )}
                    </div>
                )}
                 {/* Hidden table for PDF export */}
                {campaigns && (
                    <div className="hidden">
                        <table id="campaign-table-for-export">
                            <thead><tr><th>Campaign</th><th>Spend (€)</th><th>Impressions</th><th>Clicks</th><th>CTR (%)</th><th>CPC (€)</th><th>Purchases</th><th>ROAS</th><th>CPP (€)</th></tr></thead>
                            <tbody>{campaigns.map(c => (<tr key={c.name}><td>{c.name}</td><td>{c.spend.toFixed(2)}</td><td>{c.impressions.toLocaleString()}</td><td>{c.clicks.toLocaleString()}</td><td>{c.ctr.toFixed(2)}</td><td>{c.cpc.toFixed(2)}</td><td>{c.purchases.toLocaleString()}</td><td>{c.roas.toFixed(2)}</td><td>{c.cpp.toFixed(2)}</td></tr>))}</tbody>
                        </table>
                    </div>
                )}
            </main>
        </div>
    );
};

export default App;

