interface TrendChartProps {
    data: DailyDataPoint[];
    translations: Record<string, string>;
    language: 'en' | 'fr' | 'ar';
}

type KpiKey = 'spend' | 'roas' | 'purchases';

export const TrendChart: React.FC<TrendChartProps> = ({ data, translations: t, language }) => {
    const [visibleKpi, setVisibleKpi] = useState<KpiKey>('spend');

    const kpiConfig = {
        spend: { color: "#63B3ED", name: `${t.spendLabel} (€)` },
        roas: { color: "#48BB78", name: t.roasLabel },
        purchases: { color: "#F6E05E", name: t.purchasesLabel },
    };

    const formatDate = (dateString: string) => {
        try {
            const date = new Date(dateString);
             // Using numeric for day and month, and 2-digit for year provides a concise, locale-aware format.
            return new Intl.DateTimeFormat(language, {
                year: '2-digit',
                month: 'numeric',
                day: 'numeric',
            }).format(date);
        } catch (e) {
            return dateString; // Fallback to the original string if parsing fails
        }
    };

    return (
        <div className="bg-gray-800 p-4 sm:p-6 rounded-lg shadow-xl">
            <div className="flex flex-col sm:flex-row justify-between items-center mb-4">
                <h3 className="text-xl font-semibold text-white mb-4 sm:mb-0">{t.temporalAnalysisTitle}</h3>
                <div className="flex items-center space-x-2 bg-gray-900 p-1 rounded-lg">
                    {(Object.keys(kpiConfig) as KpiKey[]).map(key => (
                        <button 
                            key={key} 
                            onClick={() => setVisibleKpi(key)}
                            className={`px-3 py-1 text-sm font-semibold rounded-md transition-colors ${visibleKpi === key ? 'bg-blue-600 text-white' : 'text-gray-300 hover:bg-gray-700'}`}
                        >
                            {kpiConfig[key].name}
